import React, { useState, useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import Controllers from "components/Controllers/Controllers";
import {
  setResponseCount,
  setSoapNote,
} from "Reducers/scribeReducer/scribeActions";
import "./Summary.scss";

const Summary = () => {
  const dispatch = useDispatch();
  const { soapNotes, responseCount } = useSelector((state) => state.scribe);

  // State for valid response count
  const [validResponseCount, setValidResponseCount] = useState(
    responseCount || 1
  );

  const [editableContent, setEditableContent] = useState({
    subjective: "No data available for subjective",
    objective: "No data available for objective",
    assessment: "No data available for assessment",
    plan: "No data available for plan",
  });
  useEffect(() => {
    let updatedValidResponseCount = 0;
    if (responseCount && soapNotes?.length) {
      updatedValidResponseCount = Math.max(
        1,
        Math.min(responseCount, soapNotes.length)
      );
    }

    setValidResponseCount(updatedValidResponseCount);

    const updatedSoapNote = soapNotes || [];
    const currentSoapNote =
      updatedSoapNote[updatedValidResponseCount - 1] || {};
    const newEditableContent = {
      subjective: currentSoapNote.subjective?.length
        ? currentSoapNote.subjective.join("\n")
        : "No data available for subjective",
      objective: currentSoapNote.objective?.length
        ? currentSoapNote.objective.join("\n")
        : "No data available for objective",
      assessment: currentSoapNote.assessment?.length
        ? currentSoapNote.assessment.join("\n")
        : "No data available for assessment",
      plan: currentSoapNote.plan?.length
        ? currentSoapNote.plan.join("\n")
        : "No data available for plan",
    };

    setEditableContent(newEditableContent);
  }, [responseCount, soapNotes, dispatch]);

  const handleInputChange = (section, value) => {
    setEditableContent({ ...editableContent, [section]: value });
  };

  const handleBlur = (section) => {
    const updatedContent = editableContent[section]
      .split("\n")
      .filter((item) => item.trim() !== "");
    const newContent =
      updatedContent.length > 0
        ? updatedContent
        : [`No data available for ${section}`];

    const existingContent =
      soapNotes?.[validResponseCount - 1]?.[section]?.join("\n") || "";
    const isContentUnchanged = existingContent === newContent.join("\n");

    if (isContentUnchanged) {
      return;
    }
    const updatedSoapNote = {
      ...soapNotes?.[validResponseCount - 1],
      [section]: newContent,
    };
    dispatch(setSoapNote(updatedSoapNote));
    setEditableContent({
      ...editableContent,
      [section]: newContent.join("\n"),
    });
    dispatch(setResponseCount(soapNotes.length + 1));
  };

  const renderSection = (section) => {
    const sectionTitle = section.charAt(0).toUpperCase() + section.slice(1);

    return (
      <div className="soapBox" key={section}>
        <div className="soapBoxHeader">{sectionTitle}</div>
        <textarea
          className="soapBoxContent custom-scrollbar"
          value={editableContent[section] || ""}
          onChange={(e) => handleInputChange(section, e.target.value)}
          onBlur={() => handleBlur(section)}
        />
      </div>
    );
  };

  const isSoapNoteAvailable =
    soapNotes?.[validResponseCount - 1] &&
    Object.keys(soapNotes[validResponseCount - 1]).some(
      (key) =>
        Array.isArray(soapNotes[validResponseCount - 1][key]) &&
        soapNotes[validResponseCount - 1][key].length > 0
    );

  const handlePrevClick = () => {
    if (validResponseCount > 1) {
      dispatch({
        type: "SET_RESPONSE_COUNT",
        payload: validResponseCount - 1,
      });
    }
  };

  const handleNextClick = () => {
    if (validResponseCount < soapNotes?.length) {
      dispatch({
        type: "SET_RESPONSE_COUNT",
        payload: validResponseCount + 1,
      });
    }
  };

  return (
    <>
      <div className="soapController">
        <div className="tempplateHeader">
          <p>SOAP (Default Template)</p>
        </div>
        <div className="qpeResponseCount">
          <button
            disabled={validResponseCount <= 1 || soapNotes?.length === 0}
            onClick={handlePrevClick}
          >
            {"<"}
          </button>
          <p>{`${soapNotes?.length > 0 ? validResponseCount : 0} / ${
            soapNotes?.length > 0 ? soapNotes?.length : 0
          }`}</p>
          <button
            disabled={
              validResponseCount >= soapNotes?.length || soapNotes?.length === 0
            }
            onClick={handleNextClick}
          >
            {">"}
          </button>
        </div>

        <Controllers
          selectedTab="AI Summary"
          selectedSOAP={
            isSoapNoteAvailable ? soapNotes[validResponseCount - 1] : undefined
          }
          disabled={!isSoapNoteAvailable}
        />
      </div>

      <div className="soapGrid">
        {["subjective", "objective", "assessment", "plan"].map((section) =>
          renderSection(section)
        )}
      </div>
    </>
  );
};

export default Summary;
