import "./App.css";
import React, { useCallback, useEffect, useRef, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import Loader from "components/Loader/Loader";
import Index from "pages/Index/Index";
import Scribe from "pages/scribe/Scribe";
import Questionnaire from "components/Questionnaire/Questionnaire";
import {
  setDataLinkType,
  setDataDemographicid,
  setPatientName,
  setPhoneNumber,
  setAppointmentNumber,
  setEmail,
  setPhn,
  setDob,
  setDataStateClear,
  setInProgress,
  setDoctorName,
  setPreviousData,
} from "Reducers/dataReducer/dataActions";
import { useAuthentication } from "hooks/useAuthentication";
import Auth from "pages/Auth/Auth";
import {
  fetchPatientInfo,
  fetchPreviousData,
} from "services/apiService/apiService";
import {
  setResponseCount,
  setScribeDataClear,
  setSoapNote,
  setTranscript,
} from "Reducers/scribeReducer/scribeActions";
import { setTwilioDataClear } from "Reducers/twilioReducer/twilioActions";
import { logMessage } from "utils/errorLogger";
import { closeWebSocket } from "services/twilio/websocketService";
import {
  setIsCallActive,
  setIsCallAlreadyConnected,
  setIsCallDisconnected,
  setIsCallMuted,
  setIsCallRinging,
} from "Reducers/twilioReducer/twilioActions";
import {
  setAccordionData,
  setFirstApiQuestions,
  setIsAppointmentQuestionnaireLoaded,
  setIsNewPatientQuestionnaireLoaded,
  setSecondApiQuestions,
} from "Reducers/questionnaireReducer/questionnaireActions";

const MainContent = ({ controller }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [hasFetchedData, setHasFetchedData] = useState(false);
  const [selectedTab, setSelectedTab] = useState("");
  const [eventData, setEventData] = useState(null);
  const [isFetchingPatientInfo, setIsFetchingPatientInfo] = useState(false);
  const { linkType, inProgress } = useSelector((state) => state.data);
  const dispatch = useDispatch();

  const messageHandler = useRef();
  const hasPrevDataFetchedRef = useRef(false);
  const authStatus = useAuthentication();
  const currentWindow = window.location.href;

  const PROVIDER_WINDOW =
    process.env.NODE_ENV === "production"
      ? process.env.REACT_APP_PROVIDER_WINDOW
      : window.location.href;

  const ENCOUNTER_WINDOW =
    process.env.NODE_ENV === "production"
      ? process.env.REACT_APP_ENCOUNTER_WINDOW
      : window.location.href;

  const actions = {
    setIsCallMuted: (muted) => dispatch(setIsCallMuted(muted)),
    setIsCallDisconnected: (status) => dispatch(setIsCallDisconnected(status)),
    setIsCallActive: (status) => dispatch(setIsCallActive(status)),
    setIsCallRinging: (status) => dispatch(setIsCallRinging(status)),
    setIsCallAlreadyConnected: (status) =>
      dispatch(setIsCallAlreadyConnected(status)),
  };

  useEffect(() => {
    setIsAuthenticated(authStatus);
  }, [authStatus]);

  const clearAllState = () => {
    const actionType = "CLEAR_STATES";
    dispatch(setDataStateClear({ type: actionType }));
    dispatch(setScribeDataClear({ type: actionType }));
    dispatch(setTwilioDataClear({ type: actionType }));
  };

  const clearQuestionnaireStates = useCallback(() => {
    dispatch(setFirstApiQuestions(null));
    dispatch(setSecondApiQuestions(null));
    dispatch(setIsNewPatientQuestionnaireLoaded(false));
    dispatch(setIsAppointmentQuestionnaireLoaded(false));
    dispatch(setAccordionData([]));
  }, [dispatch]);

  messageHandler.current = (event) => {
    if (event.source !== window) return;

    if (event.data.type === "UPDATE_DEMOGRAPHIC_INFO") {
      const { demographicId, appointmentNumber } = event.data;

      if (demographicId && !inProgress) {
        clearAllState();
        setEventData({ demographicId, appointmentNumber });
        setHasFetchedData(false);
      } else {
        logMessage({ type: "info", message: "A session is in progress." });
      }
    } else if (event.data.type === "DISCONNECTED_CALL") {
      logMessage("", "==========[ CLOSING WEBSOCKET ]==========", false);
      closeWebSocket(actions, dispatch);
      dispatch(setInProgress(false));
    }
  };

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      setIsLoading(false);
    }, 2000);

    const handler = (event) => {
      return messageHandler.current(event);
    };

    window.addEventListener("message", handler, {
      signal: controller.signal,
    });

    return () => {
      window.removeEventListener("message", handler);
      clearTimeout(timeoutId);
    };
  }, [controller.signal]);

  useEffect(() => {
    if (isAuthenticated && eventData && !hasFetchedData && !inProgress) {
      const { demographicId, appointmentNumber } = eventData;
      hasPrevDataFetchedRef.current = false;

      const fetchPatientDetails = async () => {
        setIsFetchingPatientInfo(true);
        try {
          logMessage("info", "Fetching patient info...", false);
          dispatch(setDataDemographicid(demographicId));
          const response = await fetchPatientInfo(
            demographicId,
            appointmentNumber
          );

          if (response) {
            const { patientDetails, appointmentDetails } = response;
            clearQuestionnaireStates();

            if (patientDetails) {
              const patientInfo = {
                name: patientDetails.name || "N/A",
                email: patientDetails.email || "N/A",
                phn: patientDetails.phn || "N/A",
                dob: patientDetails.dob || "N/A",
              };

              dispatch(setPatientName(patientInfo.name));
              dispatch(setEmail(patientInfo.email));
              dispatch(setPhn(patientInfo.phn));
              dispatch(setDob(patientInfo.dob));
            }

            if (appointmentDetails) {
              const appointmentInfo = {
                appointmentType: appointmentDetails.appointmentType || "N/A",
                providerName: appointmentDetails.providerName || "N/A",
                appointmentPhoneNumber:
                  appointmentDetails.appointmentPhoneNumber || "N/A",
              };

              dispatch(setDataLinkType(appointmentInfo.appointmentType));
              dispatch(setDoctorName(appointmentInfo.providerName));
              dispatch(setPhoneNumber(appointmentInfo.appointmentPhoneNumber));
              dispatch(setAppointmentNumber(appointmentNumber || "N/A"));

              const filterSoapNotes = async (soapnotes) => {
                const transformedNotes = soapnotes.map((note) => {
                  const { subjective, objective, assessment, plan } =
                    note.soapnote || {};
                  return {
                    subjective: Array.isArray(subjective) ? subjective : [],
                    objective: Array.isArray(objective) ? objective : [],
                    assessment: Array.isArray(assessment) ? assessment : [],
                    plan: Array.isArray(plan) ? plan : [],
                  };
                });

                return transformedNotes.filter(
                  (note) =>
                    Array.isArray(note.subjective) &&
                    Array.isArray(note.objective) &&
                    Array.isArray(note.assessment) &&
                    Array.isArray(note.plan)
                );
              };

              if (!hasPrevDataFetchedRef.current) {
                hasPrevDataFetchedRef.current = true;
                fetchPreviousData(appointmentNumber)
                  .then(async (data) => {
                    if (data) {
                      dispatch(setPreviousData(data));
                      if (data.transcript) {
                        dispatch(setTranscript(data.transcript));
                      }
                      if (data.soapnotes) {
                        const filteredNotes = await filterSoapNotes(
                          data.soapnotes
                        );
                        dispatch(setSoapNote(filteredNotes));
                        dispatch(setResponseCount(filteredNotes?.length));
                        logMessage(
                          "info",
                          "SOAP notes successfully fetched.",
                          false
                        );
                      }
                    } else {
                      dispatch(setPreviousData(null));
                    }
                  })
                  .catch((error) => {
                    logMessage(
                      "error",
                      `Error fetching previous data: ${error}`,
                      false
                    );
                    dispatch(setPreviousData(null));
                  });
              } else {
                dispatch(setPreviousData(null));
              }
            }
          }
        } catch (error) {
          logMessage("error", `Error fetching patient info : ${error}`, false);
        } finally {
          logMessage("info", "Patient info fetched", false);
          setHasFetchedData(true);
          setIsFetchingPatientInfo(false);
        }
      };

      fetchPatientDetails();
    }
  }, [
    isAuthenticated,
    eventData,
    hasFetchedData,
    inProgress,
    dispatch,
    clearQuestionnaireStates,
  ]);

  // Manage selectedTab based on linkType
  useEffect(() => {
    if (linkType === "Phone call") {
      setSelectedTab("Phone");
    } else if (linkType === "Video call") {
      setSelectedTab("Virtual Appointment");
    } else if (linkType === "Clinic") {
      setSelectedTab("Clinic");
    }
  }, [linkType]);

  const renderComponent = () => {
    if (!isAuthenticated) {
      return <Auth authenticated={() => setIsAuthenticated(true)} />;
    }

    if (currentWindow.includes(PROVIDER_WINDOW)) {
      if (
        linkType === "Clinic" ||
        linkType === "Phone call" ||
        linkType === "Video call"
      ) {
        return (
          <Scribe
            key="Scribe"
            selectedTab={selectedTab}
            setSelectedTab={setSelectedTab}
          />
        );
      } else {
        return <Index key="Index" />;
      }
    }

    if (currentWindow.includes(ENCOUNTER_WINDOW)) {
      return <Questionnaire key="Questionnaire" />;
    }

    return <Index key="IndexFallback" />;
  };

  // Show loader if authenticated but still fetching patient info or link type
  const shouldShowLoader = isLoading || isFetchingPatientInfo;

  return <>{shouldShowLoader ? <Loader /> : renderComponent()}</>;
};

export default MainContent;
