import {
  createStore,
  combineReducers,
  applyMiddleware,
} from "@reduxjs/toolkit";
import dataReducer from "./dataReducer/dataReducer";
import scribeReducer from "./scribeReducer/scribeReducer";
import twilioReducer from "./twilioReducer/twilioReducer";
import { thunk } from "redux-thunk";
import userReducer from "./userReducer/userReducer";
import questionnaireReducer from "./questionnaireReducer/questionnaireReducer";
import videoCallReducer from "./videoCallReducer/videoCallReducer";

const rootReducer = combineReducers({
  data: dataReducer,
  scribe: scribeReducer,
  twilio: twilioReducer,
  user: userReducer,
  questionnaire: questionnaireReducer,
  video: videoCallReducer,
});

const store = createStore(rootReducer, applyMiddleware(thunk));

export default store;
