import {
  SET_DEVICE_READY,
  SET_CALL_BUTTON_DISABLED,
  SET_HANGUP_BUTTON_DISABLED,
  SET_MUTE_BUTTON_DISABLED,
  SET_IS_CALL_MUTED,
  SET_IS_CALL_RINGING,
  SET_IS_CALL_ACTIVE,
  SET_IS_CALL_ALREADY_CONNECTED,
  SET_IS_CALL_DISCONNECTED,
  CLEAR_STATES,
} from "./twilioActionConstants";

const initialState = {
  isDeviceReady: false,
  callButtonDisabled: false,
  hangupButtonDisabled: false,
  muteButtonDisabled: false,
  isCallMuted: false,
  isCallRinging: false,
  isCallActive: false,
  isCallAlreadyConnected: false,
  isDisconnected: false,
};

const twilioReducer = (state = initialState, action) => {
  switch (action.type) {
    case SET_DEVICE_READY:
      return { ...state, isDeviceReady: action.payload };
    case SET_CALL_BUTTON_DISABLED:
      return { ...state, callButtonDisabled: action.payload };
    case SET_HANGUP_BUTTON_DISABLED:
      return { ...state, hangupButtonDisabled: action.payload };
    case SET_MUTE_BUTTON_DISABLED:
      return { ...state, muteButtonDisabled: action.payload };
    case SET_IS_CALL_MUTED:
      return { ...state, isCallMuted: action.payload };
    case SET_IS_CALL_RINGING:
      return { ...state, isCallRinging: action.payload };
    case SET_IS_CALL_ACTIVE:
      return { ...state, isCallActive: action.payload };
    case SET_IS_CALL_ALREADY_CONNECTED:
      return { ...state, isCallAlreadyConnected: action.payload };
    case SET_IS_CALL_DISCONNECTED:
      return { ...state, isDisconnected: action.payload };
    case CLEAR_STATES:
      return initialState;
    default:
      return state;
  }
};

export default twilioReducer;
