import React from "react";
import { logMessage } from "utils/errorLogger";

const RenderAnswer = ({ item }) => {
  const { type, answer } = item;

  if (answer === null || answer === undefined) {
    return <span className="qpeQuestionnaireAnswer">Not provided</span>;
  }

  switch (type) {
    case "jsonlist":
      if (Array.isArray(answer.value)) {
        return (
          <ul className="qpeQuestionnaireAnswer qpeQuestionnaireList">
            {answer.value.length > 0 ? (
              answer.value?.map((val, index) => (
                <li key={index} className="qpeQuestionnaireListItem">
                  <span>{val.itemName || "Not provided"}</span>
                </li>
              ))
            ) : (
              <span>Not provided</span>
            )}
          </ul>
        );
      } else if (typeof answer.value === "object" && answer.value !== null) {
        return (
          <span className="qpeQuestionnaireAnswer">
            {answer.value.itemName || "No data available"}
          </span>
        );
      } else {
        return (
          <span className="qpeQuestionnaireAnswer">Invalid data format</span>
        );
      }

    case "number":
    case "phoneNumber":
      return (
        <span className="qpeQuestionnaireAnswer">
          {answer === null || answer === "" ? "Not provided" : answer}
        </span>
      );

    case "select":
      return (
        <span className="qpeQuestionnaireAnswer">
          {answer === null || answer === "" ? "Not provided" : answer}
        </span>
      );

    case "switch":
      return (
        <span className="qpeQuestionnaireAnswer">{answer ? "Yes" : "No"}</span>
      );

    case "textfield":
    case "date-drop-down":
    case "textarea":
      return (
        <span className="qpeQuestionnaireAnswer">
          {answer === null ? "Not provided" : answer}
        </span>
      );

    case "datagrid": {
      let arrayAnswers = answer;

      if (typeof answer === "string") {
        try {
          arrayAnswers = JSON.parse(answer);
        } catch (error) {
          logMessage("error", `Error parsing datagrid answer : ${error}`, false);
          return (
            <span className="qpeQuestionnaireAnswer">Invalid data format</span>
          );
        }
      }

      // Check if the datagrid key is "vaccineGrid"
      if (item.key === "vaccineGrid") {
        return (
          <ul className="qpeQuestionnaireAnswer qpeQuestionnaireList">
            {arrayAnswers[0] &&
              Object.keys(arrayAnswers[0])?.map((containerKey, index) => {
                const container = arrayAnswers[0][containerKey];
                const arrayList =
                  container?.[Object.keys(container)[0]]?.value || [];
                const subAnswer =
                  container?.[Object.keys(container)[0] + "_value"] ||
                  "Not provided";

                if (!arrayList.length || !arrayList[0].itemName) return null;

                return (
                  <li key={index} className="qpeQuestionnaireListItem">
                    <span>{arrayList[0].itemName}</span>
                    <span> - {subAnswer}</span>
                  </li>
                );
              })}
          </ul>
        );
      } else if (item.key === "takeGrid") {
        return (
          <ul className="qpeQuestionnaireAnswer qpeQuestionnaireList">
            {arrayAnswers[0] &&
              Object.keys(arrayAnswers[0])?.map((containerKey, index) => {
                const container = arrayAnswers[0][containerKey];
                const valueArray = container?.value || [];
                const subAnswer =
                  arrayAnswers[0][`${containerKey}_value`] || "Not provided";

                if (!valueArray.length || !valueArray[0].itemName) return null;
                return (
                  <li key={index} className="qpeQuestionnaireListItem">
                    <span>{valueArray[0].itemName}</span>
                    <span> {subAnswer}</span>
                  </li>
                );
              })}
          </ul>
        );
      } else if (Array.isArray(answer)) {
        return (
          <ul className="qpeQuestionnaireAnswer qpeQuestionnaireList">
            {answer.length > 0 ? (
              answer.map((val, index) => (
                <li key={index} className="qpeQuestionnaireListItem">
                  {Object.entries(val)?.map(([key, value]) => (
                    <div key={key}>
                      <strong>{key} - </strong>
                      <span>
                        {typeof value === "object"
                          ? JSON.stringify(value)
                          : value || "Not provided"}
                      </span>
                    </div>
                  ))}
                </li>
              ))
            ) : (
              <span>Not provided</span>
            )}
          </ul>
        );
      }

      break;
    }

    default:
      return (
        <span className="qpeQuestionnaireAnswer">Unsupported type: {type}</span>
      );
  }
};
export default RenderAnswer;
