import { DATA_CONSTANTS } from "Reducers/dataReducer/dataActionConstants";
import { scribeFactory } from "../../services/scribe";
import {
  START_RECORDING,
  STOP_RECORDING,
  PAUSE_RECORDING,
  RESUME_RECORDING,
  SET_TRANSCRIPT,
  SET_ERROR,
  SET_SOAP_NOTE,
  SET_DICTATION,
} from "./scribeActionConstants";
import { ScreenType } from "enums";
import { logMessage } from "utils/errorLogger";

let processorRef = null;

let lastTranscriptPortion = "";
let updatedDictation = "";

function createCallback(dispatch, getState) {
  return (data) => {
    if (data) {
      const parsedData = JSON.parse(data);
      const newDictation = parsedData?.transcription;

      const { dictationText } = getState().scribe;

      if (newDictation !== lastTranscriptPortion) {
        const freshContent = newDictation
          .replace(lastTranscriptPortion, "")
          .trim();

        if (freshContent) {
          updatedDictation = dictationText
            ? `${dictationText} ${freshContent}`
            : freshContent;

          logMessage("", `[ Updated Dictation ] :: ${updatedDictation}`, false);

          dispatch({ type: SET_DICTATION, payload: updatedDictation });

          lastTranscriptPortion = newDictation;
        }
      }
    } else {
      logMessage("error", `[ Error ] :: ${data}`, false);
      dispatch({ type: SET_ERROR, payload: "Invalid data received" });
    }
  };
}
export const startRecording =
  (appointmentNumber) => async (dispatch, getState) => {
    try {
      // Dispatch in-progress state
      dispatch({ type: DATA_CONSTANTS.SET_IN_PROGRESS, payload: true });
      dispatch({ type: SET_DICTATION, payload: "" });

      // Check microphone permissions
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      if (stream) {
        // If microphone is allowed, proceed
        const mode = localStorage.getItem("API_MODE") || "default";
        sessionStorage.setItem("sessionStatus", true);
        const ScribeProcessor = scribeFactory({ live: mode });

        processorRef = new ScribeProcessor(
          process.env.REACT_APP_WS_URL,
          process.env.REACT_APP_SERVER_URL,
          createCallback(dispatch, getState),
          appointmentNumber
        );

        await processorRef.getMicrophoneAccess(
          () => {
            processorRef.startRecording();
            dispatch({
              type: DATA_CONSTANTS.SET_SCREEN,
              payload: ScreenType.NONE,
            });

            dispatch({ type: START_RECORDING });
            dispatch({ type: SET_ERROR, payload: null });
          },
          (error) => {
            logMessage(
              "error",
              `Error While Accessing Microphone! ${error}`,
              false
            );
            dispatch({ type: SET_ERROR, payload: "Microphone access error" });
            dispatch({ type: DATA_CONSTANTS.SET_IN_PROGRESS, payload: false });
          }
        );
      }
    } catch (error) {
      if (error.name === "NotAllowedError") {
        dispatch({
          type: SET_ERROR,
          payload:
            "Microphone access denied. Please allow microphone permissions in your browser settings and try again.",
        });
        logMessage("error", "Pemission for microphone is denied");
      } else if (error.name === "NotFoundError") {
        dispatch({
          type: SET_ERROR,
          payload: "Microphone not found on this device",
        });
      } else {
        logMessage("error", `Error While Starting Recording: ${error}`, false);
        dispatch({ type: SET_ERROR, payload: "Failed to start recording" });
      }
      dispatch({ type: DATA_CONSTANTS.SET_IN_PROGRESS, payload: false });
    } finally {
      // Ensure processorRef exists
      if (!processorRef) {
        dispatch({ type: SET_ERROR, payload: "Processor not initialized" });
      }
    }
  };

export const stopRecording = () => async (dispatch, getState) => {
  if (!processorRef) {
    dispatch({ type: SET_ERROR, payload: "Processor not initialized" });
    return;
  }
  const { transcriptText, dictationText } = getState().scribe;

  if (transcriptText) {
    const newText = transcriptText + " " + dictationText;
    dispatch({ type: SET_TRANSCRIPT, payload: newText });
  }

  dispatch({ type: DATA_CONSTANTS.SET_IN_PROGRESS, payload: true });

  try {
    const newTranscript = await processorRef.stopRecording();

    const safeNewTranscript = newTranscript ? newTranscript.trim() : "";

    let updatedTranscript = transcriptText;

    logMessage("", `[ Transcript Text ] :: ${transcriptText}`, false);
    logMessage("", `[ Safe new Transcript ] :: ${safeNewTranscript}`, false);
    updatedTranscript = transcriptText + " " + safeNewTranscript;

    logMessage("", `[ UPDATED Transcript ] :: ${updatedTranscript}`, false);
    dispatch({ type: STOP_RECORDING, payload: updatedTranscript });
    dispatch({ type: SET_TRANSCRIPT, payload: updatedTranscript });
    dispatch({ type: DATA_CONSTANTS.SET_SCREEN, payload: ScreenType.DEFAULT });
    lastTranscriptPortion = safeNewTranscript;
    processorRef = null;
    sessionStorage.setItem("sessionStatus", false);

    dispatch({ type: DATA_CONSTANTS.SET_IN_PROGRESS, payload: false });
  } catch (error) {
    logMessage("", `[ Error Stopping Recording ] :: ${error.message}`, false);
    sessionStorage.setItem("sessionStatus", false);
    const newText = `${transcriptText} ${updatedDictation}`;
    dispatch({ type: SET_ERROR, payload: "Failed to stop recording" });
    dispatch({ type: DATA_CONSTANTS.SET_IN_PROGRESS, payload: false });
    dispatch({ type: STOP_RECORDING, payload: false });
    dispatch({ type: SET_TRANSCRIPT, payload: newText });
    dispatch({ type: STOP_RECORDING, payload: transcriptText });
    dispatch({ type: SET_TRANSCRIPT, payload: transcriptText });
    dispatch({ type: DATA_CONSTANTS.SET_SCREEN, payload: ScreenType.DEFAULT });
    logMessage("error", "Failed to transcribe the audio,No audio was recorded");
  }
};

export const pauseRecording = () => (dispatch) => {
  if (processorRef) {
    processorRef.pauseRecording();
    logMessage("", "Dispatching PAUSE_RECORDING", false);
    dispatch({ type: PAUSE_RECORDING });
  } else {
    dispatch({ type: SET_ERROR, payload: "Processor not initialized" });
  }
};

export const resumeRecording = () => (dispatch) => {
  if (processorRef) {
    dispatch({ type: DATA_CONSTANTS.SET_IN_PROGRESS, payload: true });
    processorRef.resumeRecording();
    logMessage("", "Dispatching RESUME_RECORDING", false);
    dispatch({ type: RESUME_RECORDING });
  } else {
    dispatch({ type: SET_ERROR, payload: "Processor not initialized" });
  }
};

export const setTranscript = (text) => ({
  type: SET_TRANSCRIPT,
  payload: text,
});

export const setSoapNote = (soapNote) => {
  return {
    type: SET_SOAP_NOTE,
    payload: soapNote,
  };
};

export const setDictation = (text) => ({
  type: SET_DICTATION,
  payload: text,
});

export const setStopping = (payload) => ({
  type: "SET_STOPPING",
  payload,
});

export const setScribeDataClear = () => ({
  type: "CLEAR_STATES",
});

export const setResponseCount = (payload) => ({
  type: "SET_RESPONSE_COUNT",
  payload,
});

export const setIsSoapNoteLoaded = (isLoaded) => ({
  type: "IS_SOAP_NOTE_LOADED",
  payload: isLoaded,
});
