import { useEffect } from "react";
import { logMessage } from "utils/errorLogger";

const useFetchQuestionnaires = ({
  demoGraphicId,
  appointmentNumber,
  isNewPatientQuestionnaireLoaded,
  isAppointmentQuestionnaireLoaded,
  dispatch,
  fetchQuestionnaireApi,
  setFirstApiQuestions,
  setSecondApiQuestions,
  setIsNewPatientQuestionnaireLoaded,
  setIsAppointmentQuestionnaireLoaded,
}) => {
  const fetchQuestions = async (id, type) => {
    try {
      const isLoaded =
        type === "demographicNo"
          ? isNewPatientQuestionnaireLoaded
          : isAppointmentQuestionnaireLoaded;

      if (isLoaded) {
        logMessage(
          "warning",
          `${type} questionnaire already loaded, skipping API call`,
          false
        );
        return;
      }

      const response = await fetchQuestionnaireApi(id, type, dispatch);

      if (!response || !response.questionWithAnswers) {
        logMessage("warning", `No questions found for ${type}`, false);

        if (type === "demographicNo") {
          dispatch(setFirstApiQuestions(null));
          dispatch(setIsNewPatientQuestionnaireLoaded(true));
        }

        if (type === "oscarAppointmentId") {
          dispatch(setSecondApiQuestions(null));
          dispatch(setIsAppointmentQuestionnaireLoaded(true));
        }
        return;
      }

      const parsedQuestions = JSON.parse(response.questionWithAnswers);

      if (type === "demographicNo") {
        dispatch(setFirstApiQuestions(parsedQuestions));
        dispatch(setIsNewPatientQuestionnaireLoaded(true));
      }

      if (type === "oscarAppointmentId") {
        dispatch(setSecondApiQuestions(parsedQuestions));
        dispatch(setIsAppointmentQuestionnaireLoaded(true));
      }
      logMessage("", `Questionnaire loaded for ${type}`, false);
    } catch (error) {
      logMessage("error", `Error fetching ${type} API: ${error}`, false);

      if (type === "demographicNo") {
        dispatch(setFirstApiQuestions(null));
      }

      if (type === "oscarAppointmentId") {
        dispatch(setSecondApiQuestions(null));
      }
    }
  };

  useEffect(() => {
    if (!isNewPatientQuestionnaireLoaded && demoGraphicId) {
      fetchQuestions(demoGraphicId, "demographicNo");
    }

    if (!isAppointmentQuestionnaireLoaded && appointmentNumber) {
      const strApptNO = String(appointmentNumber);
      fetchQuestions(strApptNO, "oscarAppointmentId");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    demoGraphicId,
    appointmentNumber,
    isNewPatientQuestionnaireLoaded,
    isAppointmentQuestionnaireLoaded,
    dispatch,
    fetchQuestionnaireApi,
    setFirstApiQuestions,
    setSecondApiQuestions,
    setIsNewPatientQuestionnaireLoaded,
    setIsAppointmentQuestionnaireLoaded,
  ]);
};

export default useFetchQuestionnaires;
