import { useEffect, useRef, useState } from "react";
import {
  useLocalCameraTrack,
  useLocalMicrophoneTrack,
  useRemoteUsers,
  useJoin,
  usePublish,
  LocalUser,
  RemoteUser,
  useRTCClient,
  useRemoteAudioTracks,
} from "agora-rtc-react";
import "./VideoCallScreen.scss";
import Controllers from "components/Controllers/Controllers";
import TimerDisplay from "components/TimerDisplay/TimerDisplay";
import { SelectedTab, TimerTypes } from "enums";
import PatientProfile from "components/PatientProfile/PatientProfile";
import { useSelector } from "react-redux";
import { MicIcon, MuteMicIcon, VideoIcon } from "assets/Index";
import { getInitials } from "utils/Utils";

const VideoCallScreen = () => {
  const appId = process.env.REACT_APP_AGORA_APP_ID;
  const { appointmentNumber, patientName } = useSelector((state) => state.data);
  const { micOn, cameraOn, token } = useSelector((state) => state.video);

  useJoin(
    {
      token,
      appid: appId,
      channel: appointmentNumber,
    },
    true
  );

  const { localMicrophoneTrack } = useLocalMicrophoneTrack(micOn);
  const { localCameraTrack } = useLocalCameraTrack(cameraOn);

  const videoContainerRef = useRef(null);

  usePublish([localMicrophoneTrack, localCameraTrack]);

  const remoteUsers = useRemoteUsers();
  // const audioTrack = useRemoteAudioTracks(remoteUsers);

  // audioTrack.audioTracks.map((track) => {
  //   USE this for sending audio to ws
  // });
  // console.log("-------------------------", { micOn, cameraOn });

  const handleAudioRecording = (track, type) => {
    const mediaStream = new MediaStream([track.getMediaStreamTrack()]);
    const mediaRecorder = new MediaRecorder(mediaStream);

    mediaRecorder.ondataavailable = (event) => {
      if (event.data.size > 0) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64Audio = reader.result.split(",")[1];
          // console.log(`${type} audio Base64:`, base64Audio);
        };
        reader.readAsDataURL(event.data);
      }
    };

    mediaRecorder.start(1000);

    return () => {
      mediaRecorder.stop();
    };
  };

  // useEffect(() => {
  //   if (localMicrophoneTrack) {
  //     const stopLocalRecording = handleAudioRecording(
  //       localMicrophoneTrack,
  //       "Local"
  //     );
  //     return stopLocalRecording;
  //   }
  // }, [localMicrophoneTrack]);

  useEffect(() => {
    const stopRemoteRecordings = remoteUsers.map((user) => {
      if (user.audioTrack) {
        // return handleAudioRecording(user.audioTrack, `Remote user ${user.uid}`);
      }
      return null;
    });

    return () => {
      stopRemoteRecordings.forEach((stopRecording) => {
        if (stopRecording) stopRecording();
      });
    };
  }, [remoteUsers]);

  const totalUsers = remoteUsers.length + 1;

  return (
    <div className="qpeVideoCallScreenContainer">
      <div className="qpeVideoContainer">
        <div className="video-container" ref={videoContainerRef}></div>
        <LocalUser
          cameraOn={cameraOn}
          micOn={micOn}
          videoTrack={localCameraTrack}
          audioTrack={localMicrophoneTrack}
          playAudio={false}
          cover={() => {
            return (
              <div className="local-user-placeholder">
                <PatientProfile main={false} size="medium" />
                <div className="iconContainer">
                  {micOn ? (
                    <MicIcon color="var(--primary)" />
                  ) : (
                    <MuteMicIcon color="var(--primary)" />
                  )}
                  {cameraOn ? (
                    <VideoIcon color="var(--primary)" />
                  ) : (
                    <VideoIcon color="var(--primary)" isDisabled={true} />
                  )}
                </div>
              </div>
            );
          }}
          style={{
            position: "absolute",
            zIndex: 2,
            top: "10px",
            right: "10px",
            width: "220px",
            borderRadius: "10px",
            height: "120px",
            background: "var(--white)",
          }}
        />

        {remoteUsers.map((user, index) => (
          <div
            key={user.uid}
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              transform: `translate(${index * 100}px, 0)`,
            }}
          >
            <RemoteUser
              user={user}
              playAudio={true}
              cover={() => {
                return (
                  <div className="remote-user-placeholder">
                    <div className="remote-place-holder-sub">
                      <div className="qpeTimerContainer">
                        <p>{patientName || "N/A"}</p>
                      </div>
                      <div className="qpeProfile">
                        <p>{getInitials(patientName) || "N/A"}</p>
                      </div>
                      <div className="iconContainer">
                        {remoteUsers[0].hasAudio ? (
                          <MicIcon color="var(--primary)" />
                        ) : (
                          <MuteMicIcon color="var(--primary)" />
                        )}
                        {remoteUsers[0].hasVideo ? (
                          <VideoIcon color="var(--primary)" />
                        ) : (
                          <VideoIcon color="var(--primary)" isDisabled={true} />
                        )}
                      </div>
                    </div>
                  </div>
                );
              }}
              style={{
                position: "absolute",
                width: "100%",
                height: "100%",
              }}
            />
          </div>
        ))}
      </div>

      <div className="qpeElevatedDiv">
        <TimerDisplay type={TimerTypes.NAME} />
        <Controllers
          totalUsers={totalUsers}
          selectedTab={SelectedTab.VIRTUAL_APPOINTMENT}
          videoTrack={localCameraTrack}
          micTrack={localMicrophoneTrack}
          videoContainerRef={videoContainerRef}
        />
      </div>
    </div>
  );
};

export default VideoCallScreen;
