
import { USER_CONSTANT } from "./userActionContants";

const initialState = {
    user: null,
    loading: false,
    error: null,
    isAuthenticated: false,
};

const userReducer = (state = initialState, action) => {
    switch (action.type) {
        case USER_CONSTANT.LOGIN_REQUEST:
            return {
                ...state,
                loading: true,
                error: null,
            };
        case USER_CONSTANT.LOGIN_SUCCESS:
            return {
                ...state,
                loading: false,
                user: action.payload,
                isAuthenticated: true,
                error: null,
            };
        case USER_CONSTANT.LOGIN_FAILURE:
            return {
                ...state,
                loading: false,
                error: action.payload,
                isAuthenticated: false,
            };
        case USER_CONSTANT.LOGOUT:
            return {
                ...state,
                user: null,
                isAuthenticated: false,
            };
        default:
            return state;
    }
};

export default userReducer;
