import "../../style.scss";
import { useState, useEffect, useRef } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchSoapNote } from "services/soapNoteService";
import TabNavigation from "components/TabNavigation/TabNavigation";
import TabContent from "components/TabContent/TabContent";
import {
  setResponseCount,
  setSoapNote,
} from "Reducers/scribeReducer/scribeActions";
import { SelectedTab, LinkType } from "enums";
import { setSoapApiData } from "Reducers/questionnaireReducer/questionnaireActions";

const Scribe = ({ selectedTab, setSelectedTab }) => {
  const dispatch = useDispatch();
  const {
    isRecording,
    isPaused,
    transcriptText,
    soapNote,
    responseCount,
  } = useSelector((state) => state.scribe);

  const { patientName, phoneNumber, linkType, appointmentNumber } = useSelector(
    (state) => state.data
  );
  const { secondApiQuestions } = useSelector((state) => state.questionnaire);

  const { isCallActive } = useSelector((state) => state.twilio);

  const [timer, setTimer] = useState(0);
  const [loading, setLoading] = useState(false);
  const [isStopping, setIsStopping] = useState(false);
  const [questionnaire, setQuestionnaire] = useState();
  const previousTranscript = useRef(transcriptText);
  const timerIntervalRef = useRef(null);

  useEffect(() => {
    if ((isRecording || isCallActive) && !isPaused) {
      timerIntervalRef.current = setInterval(
        () => setTimer((t) => t + 1),
        1000
      );
    }
    return () => clearInterval(timerIntervalRef.current);
  }, [isRecording, isPaused, isCallActive]);

  useEffect(() => {
    if (isStopping && !isRecording) setIsStopping(false);
  }, [isRecording, isStopping]);

  const removeKeysFromElements = (array, keysToRemove) => {
    return array?.map((item) => {
      return Object.fromEntries(
        Object.entries(item).filter(([key]) => !keysToRemove.includes(key))
      );
    });
  };

  useEffect(() => {
    if (secondApiQuestions) {
      const jsonQuestionnaire = {
        appointment: removeKeysFromElements(secondApiQuestions, [
          "key",
          "type",
        ]),
      };
      setQuestionnaire(jsonQuestionnaire);
      dispatch(setSoapApiData(jsonQuestionnaire));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dispatch, isRecording, selectedTab]);

  useEffect(() => {
    if (
      !isRecording &&
      selectedTab === SelectedTab.AI_SUMMARY &&
      transcriptText !== previousTranscript.current
    ) {
      previousTranscript.current = transcriptText;
      setLoading(true);
      fetchSoapNote(transcriptText, questionnaire, appointmentNumber)
        .then((result) => {
          if (result && result.soapnote) {
            dispatch(setSoapNote(result.soapnote));
            dispatch(setResponseCount(responseCount + 1));
          } else {
            dispatch(setSoapNote({}));
          }
        })
        .catch((err) => {
          console.error("Error fetching SOAP note:", err);
          dispatch(setSoapNote({}));
        })
        .finally(() => setLoading(false));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isRecording, selectedTab, transcriptText, dispatch, responseCount]);

  const hasSoapNoteData =
    soapNote &&
    ["subjective", "objective", "assessment", "plan"].some(
      (section) => soapNote[section]?.length > 0
    );

  useEffect(() => {
    if (linkType === LinkType.CLINIC) {
      setSelectedTab(SelectedTab.CLINIC);
    } else if (linkType === LinkType.PHONE_CALL) {
      setSelectedTab(SelectedTab.PHONE_APPOINTMENT);
    } else if (linkType === LinkType.VIDEO_CALL) {
      setSelectedTab(SelectedTab.VIRTUAL_APPOINTMENT);
    }
  }, [linkType, setSelectedTab]);

  const renderComponent = () => {
    return (
      <div className="qpeContextContainer">
        <TabContent
          selectedTab={selectedTab}
          timer={timer}
          patientName={patientName}
          soapNote={soapNote}
          loading={loading}
          hasSoapNoteData={hasSoapNoteData}
          dispatch={dispatch}
          phoneNumber={phoneNumber}
          setTimer={setTimer}
          questionnaire={questionnaire}
        />
      </div>
    );
  };

  return (
    <div className="qpeIndexMainContainer">
      <div className="qpeSub-container">
        <div className="qpeTop-container">
          <TabNavigation
            selectedTab={selectedTab}
            setSelectedTab={setSelectedTab}
          />
        </div>
        <div className="qpeOuterContainer">{renderComponent()}</div>
      </div>
    </div>
  );
};

export default Scribe;
