import toast from "react-hot-toast";
import { logMessage } from "./errorLogger";

let isToastVisible = false;

export const showToast = (type, message) => {
  if (isToastVisible) {
    return;
  }
  const InfoIcon = ({ style }) => (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width="24"
      height="24"
      style={{
        fill: "#007bff",
        animation: "pulse 1s infinite",
        ...style,
      }}
    >
      <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm-1-13h2v6h-2zm0 8h2v2h-2z" />
    </svg>
  );

  isToastVisible = true;

  toast.dismiss();

  const toastMethods = {
    success: (msg) => toast.success(msg),
    error: (msg) => toast.error(msg),
    info: (msg) =>
      toast.custom((t) => (
        <div
          className="qpe-toast"
          style={{
            padding: "10px 20px",
            backgroundColor: "#f0f0f0",
            borderRadius: "8px",
            color: "#333",
            display: "flex",
            alignItems: "center",
            fontSize: "14px",
          }}
        >
          <InfoIcon
            style={{
              marginRight: "10px",
              color: "#007bff",
              fontSize: "18px",
              animation: "pulse 1s infinite", // Apply pulse animation
            }}
          />
          <span>{msg}</span>
        </div>
      )),
  };

  const normalizedMode = type?.toLowerCase();
  const showToastFn = toastMethods[normalizedMode];

  if (showToastFn) {
    showToastFn(message);
  } else {
    logMessage("error", `Invalid Toast Type: "${type}" `,false);
  }

  setTimeout(() => {
    isToastVisible = false;
  }, 3000);
};
