import { logMessage } from "utils/errorLogger";

export const DeepgramLive = (Base) =>
  class extends Base {
    constructor(...args) {
      super(...args);
      this.heartbeatInterval = null;
    }

    wsOnMessage(e) {
      const data = e?.data;
      if (data) {
        this.cb(data);
      } else {
        logMessage("error", `Invalid data received :: ${e}`, false);
      }
    }

    mediaRecorderOnDataAvailable(e) {
      this.audioChunks.push(e.data);
      const arrayBufferToBase64 = async (arrayBuffer) => {
        const uint8Array = new Uint8Array(arrayBuffer);
        const base64Audio = btoa(
          uint8Array.reduce(
            (data, byte) => data + String.fromCharCode(byte),
            ""
          )
        );
        return base64Audio;
      };

      e.data.arrayBuffer().then(async (arrayBuffer) => {
        try {
          const base64Audio = await arrayBufferToBase64(arrayBuffer);
          const message = JSON.stringify({
            appt_id: this.appointmentNumber,
            audio: base64Audio,
          });
          if (this.ws && this.ws.readyState === WebSocket.OPEN) {
            this.ws.send(message);
          }
        } catch (error) {
          logMessage(
            "error",
            `Error converting audio to base64: ${error}`,
            false
          );
        }
      });
    }

    startHeartbeat() {
      if (this.heartbeatInterval) {
        clearInterval(this.heartbeatInterval);
      }

      this.heartbeatInterval = setInterval(() => {
        if (this.ws && this.ws.readyState === WebSocket.OPEN) {
          const keepAliveMessage = JSON.stringify({ type: "KeepAlive" });
          this.ws.send(keepAliveMessage);
          this.ws.send(keepAliveMessage);
          this.logData("Sent heartbeat: KeepAlive x2");
        } else {
          this.logData("WebSocket is not open. Stopping heartbeat.");
          clearInterval(this.heartbeatInterval);
          this.heartbeatInterval = null;
        }
      }, 3000);
    }

    stopHeartbeat() {
      if (this.heartbeatInterval) {
        clearInterval(this.heartbeatInterval);
        this.heartbeatInterval = null;
        this.logData("Stopped heartbeat.");
      }
    }

    startRecording() {
      if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
        this.initWSConnection(this.wsUrl);
        this.ws.onopen = (e) => {
          this.wsOnOpen(e);
          this.logData("WebSocket connected, starting recording...");
          navigator.mediaDevices
            .getUserMedia({ audio: true, video: false })
            .then((stream) => {
              this.initializeMediaRecorder(stream);
              if (this.mediaRecorder) {
                this.logData(
                  `MediaRecorder initialized with state: ${this.mediaRecorder.state} and id: ${this.mediaRecorder.stream.id}`
                );
              } else {
                this.logData("MediaRecorder could not be initialized.");
              }
            })
            .catch((error) => {
              this.logData("Error accessing microphone:", error);
            });
        };
        this.ws.onclose = (e) => {
          this.logData(
            "=================[ CLOSING WEBSOCKET ]================="
          );
        };
      } else {
        this.logData("WebSocket is already open, starting recording...");
        // Get user media for audio
        navigator.mediaDevices
          .getUserMedia({ audio: true, video: false })
          .then((stream) => {
            this.initializeMediaRecorder(stream);
            if (this.mediaRecorder) {
              this.logData(
                `MediaRecorder initialized with state: ${this.mediaRecorder.state} and id: ${this.mediaRecorder.stream.id}`
              );
            } else {
              this.logData("MediaRecorder could not be initialized.");
            }
          })
          .catch((error) => {
            this.logData("Error accessing microphone:", error);
          });
      }
    }

    pauseRecording() {
      if (this.mediaRecorder && this.mediaRecorder.state === "recording") {
        this.mediaRecorder.pause();
        this.startHeartbeat();
        this.logData("Recording paused");
      } else {
        logMessage(
          "error",
          "Cannot pause recording - MediaRecorder is not recording or is null.",
          false
        );
      }
    }

    resumeRecording() {
      this.stopHeartbeat();
      this.logData("Resuming recording...");
      if (this.mediaRecorder && this.mediaRecorder.state === "paused") {
        this.mediaRecorder.resume();
        this.logData("Recording resumed");
      } else {
        logMessage(
          "error",
          "Cannot resume recording - MediaRecorder is not paused or is null.",
          false
        );
      }
    }

    async stopRecording(setTranscriptText, setIsDictationChanged) {
      try {
        this.mediaRecorder.stop();
        await new Promise((resolve) => {
          this.mediaRecorder.onstop = resolve;
        });
        this.logData(
          `MediaRecorder stopped with state: ${this.mediaRecorder.state}`
        );
        if (this.mediaRecorder.stream) {
          this.mediaRecorder.stream.getTracks().forEach((track) => {
            if (track.readyState === "live") {
              this.logData(
                `Stopping track: ${track.kind}, track id: ${track.id}`
              );
              track.stop();
            }
          });
        }

        this.stopHeartbeat();

        if (
          this.ws &&
          this.ws.readyState !== WebSocket.CLOSED &&
          this.ws.readyState !== WebSocket.CLOSING
        ) {
          this.logData("Closing WebSocket connection.");
          this.ws.close();
        } else {
          this.logData(
            "WebSocket is already closed or in the process of closing."
          );
        }

        // Transcribe the full audio
        const transcribeText = await this.transcribeFullAudio(
          setTranscriptText,
          setIsDictationChanged
        );
        return transcribeText;
      } catch (error) {
        this.logData(`Error in stopRecording: ${error.message}`);
        throw error;
      }
    }
  };
