import { AccordionIcon } from "assets/Index";
import React from "react";

const Accordion = ({ data, index, toggleAccordion, activeIndex }) => {
  const isActive = activeIndex === index;

  return (
    <div className={`qpeAccordionItem`}>
      <div
        className={`qpeAccordionHeader ${isActive ? "Hactive" : ""}`}
        onClick={() => toggleAccordion(index)}
      >
        <p>{data.title}</p>
        <span className="qpeAccordionIcon">
          {isActive ? <AccordionIcon /> : <AccordionIcon isOpen={true} />}
        </span>
      </div>
      <div
        className={`qpeAccordionContent custom-scrollbar over ${
          isActive ? "active" : ""
        }`}
      >
        {data.renderContent(data.questions)}
      </div>
    </div>
  );
};

export default Accordion;
