// questionnaireReducer.js
import {
  SET_FIRST_API_QUESTIONS,
  SET_SECOND_API_QUESTIONS,
  SET_IS_APPOINTMENT_QUESTIONNAIRE_LOADED,
  SET_IS_NEW_PATIENT_QUESTIONNAIRE_LOADED,
  SET_ACCORDION_DATA,
  CLEAR_STATES,
  SET_SOAP_API_DATA,
} from "./questionnaireActionConstants";

const initialState = {
  firstApiQuestions: null,
  secondApiQuestions: null,
  isAppointmentQuestionnaireLoaded: false,
  isNewPatientQuestionnaireLoaded: false,
  accordionData: [],
  soapApiData: null,
};

const questionnaireReducer = (state = initialState, action) => {
  switch (action.type) {
    case SET_FIRST_API_QUESTIONS:
      return {
        ...state,
        firstApiQuestions: action.payload,
      };
    case SET_SECOND_API_QUESTIONS:
      return {
        ...state,
        secondApiQuestions: action.payload,
      };
    case SET_IS_APPOINTMENT_QUESTIONNAIRE_LOADED:
      return {
        ...state,
        isAppointmentQuestionnaireLoaded: action.payload,
      };
    case SET_IS_NEW_PATIENT_QUESTIONNAIRE_LOADED:
      return {
        ...state,
        isNewPatientQuestionnaireLoaded: action.payload,
      };
    case SET_ACCORDION_DATA:
      return {
        ...state,
        accordionData: action.payload,
      };
    case CLEAR_STATES:
      return initialState;
    case SET_SOAP_API_DATA:
      return {
        ...state,
        soapApiData: action.payload,
      };
    default:
      return state;
  }
};

export default questionnaireReducer;
