import RenderAnswer from "components/RenderAnswer/RenderAnswer";
import React from "react";

const RenderQuestion = ({ questions }) => {
  if (!questions || questions.length === 0) {
    return (
      <span className="qpeQuestionnaireItem qpeQuestionnaireLabel">
        No questionnaire is available.
      </span>
    );
  }

  return questions
    .filter((item) => item.label && item.label.trim() !== "")
    .map((item, index) => (
      <div key={index} className="qpeQuestionnaireItem">
        <label className="qpeQuestionnaireLabel">{item.label}</label>
        <RenderAnswer item={item} />
      </div>
    ));
};

export default RenderQuestion;
