import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import RenderQuestion from "components/RenderQuestion/RenderQuestion";
import Accordion from "components/Accordion/Accordion";
import { setAccordionData } from "Reducers/questionnaireReducer/questionnaireActions";
import "./Questionnaire.scss";
import { SearchIcon } from "assets/Index";

function Questionnaire() {
  const dispatch = useDispatch();
  const { firstApiQuestions, secondApiQuestions } = useSelector(
    (state) => state.questionnaire
  );

  const [searchQuery, setSearchQuery] = useState("");
  const [filteredData, setFilteredData] = useState([]);
  const [activeIndex, setActiveIndex] = useState(null);

  const renderContent = (questions) => {
    if (questions === null) {
      return (
        <div className="qpeQuestionContainer">
          No questionnaire is available.
        </div>
      );
    }
    return <RenderQuestion questions={questions} />;
  };

  const accordionData = [
    {
      title: "New Patient Questionnaire",
      questions: firstApiQuestions,
      type: "demographicNo",
      renderContent: renderContent,
    },
    {
      title: "Appointment Questionnaire",
      questions: secondApiQuestions,
      type: "oscarAppointmentId",
      renderContent: renderContent,
    },
  ];

  const handleSearch = (event) => {
    const query = event.target?.value?.toLowerCase();
    setSearchQuery(query);

    const filtered = accordionData?.map((data) => ({
      ...data,
      questions: data.questions
        ? data.questions.filter((question) => {
            return (
              question?.label?.toLowerCase().includes(query) ||
              JSON.stringify(question?.answer)?.toLowerCase().includes(query)
            );
          })
        : [],
    }));

    setFilteredData(filtered);
  };

  useEffect(() => {
    if (accordionData) {
      dispatch(setAccordionData(accordionData));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dispatch, firstApiQuestions, secondApiQuestions]);

  const toggleAccordion = (index) => {
    setActiveIndex(activeIndex === index ? null : index);
  };

  return (
    <div className="qpeInnerContainer">
      <div className="qpeMajorTextContainer custom-scrollbar">
        <div className="qpeSearchContainerMain">
          <p>Appointment Questionnaire</p>
          <div className="qpeQuestionnaireSearchContainer">
            <SearchIcon />
            <input
              type="text"
              className="qpeQuestionnaireSearchInput"
              placeholder="Search"
              value={searchQuery}
              onChange={handleSearch}
            />
          </div>
        </div>
        <div className="qpeAccordionContainer">
          {(filteredData.length > 0 ? filteredData : accordionData)?.map(
            (data, index) => (
              <Accordion
                key={index}
                data={data}
                index={index}
                toggleAccordion={toggleAccordion}
                activeIndex={activeIndex}
              />
            )
          )}
        </div>
      </div>
    </div>
  );
}

export default Questionnaire;
