import { useSelector, useDispatch } from "react-redux";
import {
  setDeviceReady,
  setIsCallActive,
  setIsCallAlreadyConnected,
  setIsCallDisconnected,
  setIsCallMuted,
  setIsCallRinging,
} from "Reducers/twilioReducer/twilioActions";
import { setTranscript } from "Reducers/scribeReducer/scribeActions";
import {
  setFirstApiQuestions,
  setIsAppointmentQuestionnaireLoaded,
  setIsNewPatientQuestionnaireLoaded,
  setSecondApiQuestions,
} from "Reducers/questionnaireReducer/questionnaireActions";
import useFetchQuestionnaires from "hooks/useFetchQuestionnaires";
import { fetchQuestionnaireApi } from "services/apiService/apiService";
import { DefaultScreen } from "components/DefaultScreen/DefaultScreen";
import { LinkType } from "enums";
import AgoraRTC, { AgoraRTCProvider } from "agora-rtc-react";
import VideoCallScreen from "components/VideoCallScreen/VideoCallScreen";
import { useRef } from "react";

const AppointmentScreen = ({ selectedTab, timer, phoneNumber }) => {
  const { appointmentNumber, demoGraphicId, linkType } = useSelector(
    (state) => state.data
  );
  const { isAppointmentQuestionnaireLoaded, isNewPatientQuestionnaireLoaded } =
    useSelector((state) => state.questionnaire);
  const { isCallMuted } = useSelector((state) => state.twilio);
  const { isVideoCallActive } = useSelector((state) => state.video);

  const dispatch = useDispatch();

  const actions = {
    setDeviceReady: (ready) => dispatch(setDeviceReady(ready)),
    setIsCallMuted: (muted) => dispatch(setIsCallMuted(muted)),
    setIsCallRinging: (status) => dispatch(setIsCallRinging(status)),
    setIsCallActive: (status) => dispatch(setIsCallActive(status)),
    setTranscript: (text) => dispatch(setTranscript(text)),
    setIsCallAlreadyConnected: (status) =>
      dispatch(setIsCallAlreadyConnected(status)),
    setIsCallDisconnected: (status) => dispatch(setIsCallDisconnected(status)),
  };

  useFetchQuestionnaires({
    demoGraphicId,
    appointmentNumber,
    isNewPatientQuestionnaireLoaded,
    isAppointmentQuestionnaireLoaded,
    dispatch,
    fetchQuestionnaireApi,
    setFirstApiQuestions,
    setSecondApiQuestions,
    setIsNewPatientQuestionnaireLoaded,
    setIsAppointmentQuestionnaireLoaded,
  });

  const clientRef = useRef(null);
  if (!clientRef.current) {
    clientRef.current = AgoraRTC.createClient({ mode: "rtc", codec: "vp8" });
  }

  return (
    <div className="qpeSessionData">
      {linkType === LinkType.VIDEO_CALL && isVideoCallActive ? (
        <AgoraRTCProvider client={clientRef.current}>
          <VideoCallScreen />
        </AgoraRTCProvider>
      ) : (
        <DefaultScreen
          actions={actions}
          selectedTab={selectedTab}
          timer={timer}
          phoneNumber={phoneNumber}
          isCallMuted={isCallMuted}
        />
      )}
    </div>
  );
};

export default AppointmentScreen;
