import { logMessage } from "utils/errorLogger";

export const fetchSoapNote = async (
  dictationText,
  questionnaire,
  appointmentNumber
) => {
  const apiUrl = `${process.env.REACT_APP_SERVER_URL}/soapnote`;

  if (!apiUrl) {
    logMessage("error", "SOAP note API URL is not defined", false);
    return;
  }

  const bodyData = {
    appt_id: appointmentNumber,
    conversation: dictationText || "",
    questionnaire: {
      appointment: questionnaire?.appointment || [],
    },
  };

  try {
    const response = await fetch(apiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(bodyData),
    });

    if (!response.ok) {
      const errorDetails = await response.text();
      console.error(
        `SOAP note API request failed. Status: ${response.status}, Response: ${errorDetails}`
      );
      throw new Error(`HTTP error! Status: ${response.status}`);
    }

    const result = await response.json();
    return result;
  } catch (error) {
    logMessage(
      "error",
      `Unable to create AI summary. Error: ${error.message}`,
      false
    );
    throw error;
  }
};
