import jsPDF from "jspdf";
import NewLogo from "./image.png";
export const downloadedSOAPNote = async (soapNote) => {
  if (!soapNote) {
    throw new Error("No SOAP Note provided.");
  }

  try {
    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4",
    });

    const layout = {
      pageWidth: doc.internal.pageSize.getWidth(),
      pageHeight: doc.internal.pageSize.getHeight(),
      margins: {
        top: 10,
        bottom: 10,
        left: 10,
        right: 10,
      },
      header: { height: 40 },
      footer: { height: 25 },
      signature: { height: 30 },
    };

    const contentArea = {
      maxHeight:
        layout.pageHeight -
        layout.header.height -
        layout.footer.height -
        layout.margins.top -
        layout.margins.bottom,
      width: layout.pageWidth - layout.margins.left - layout.margins.right,
    };

    const addHeader = () => {
      doc.setFillColor("#f6fbf4");
      doc.rect(0, 0, layout.pageWidth, layout.header.height, "F");

      doc.setTextColor("#181d19");
      doc.setFontSize(22);
      doc.setFont("helvetica", "bold");
      doc.text("Medical Clinic Name", 10, 10);

      const marginBottom = 2;

      doc.setFontSize(10);
      const clinicInfo = [
        "123 Medical Center Drive",
        "City, State 12345",
        "Tel: (555) 123-4567",
        "Fax: (555) 123-4568",
      ];

      doc.setFont("helvetica", "bold");
      doc.text(clinicInfo[0], 10, 15 + marginBottom);

      doc.setFont("helvetica", "normal");
      clinicInfo.slice(1).forEach((line, index) => {
        doc.text(line, 10, 15 + marginBottom + (index + 1) * 6);
      });

      doc.setDrawColor("#c0c8cd");
      doc.setLineWidth(0.5);
      doc.line(0, layout.header.height, layout.pageWidth, layout.header.height);
    };

    const addFooter = (pageNumber) => {
      const footerY = layout.pageHeight - layout.footer.height;
      doc.setFillColor("#D1E8D5");
      doc.rect(0, footerY, layout.pageWidth, layout.footer.height, "F");

      const logoWidth = 40;
      const logoHeight = 18;
      const logoX = 4;
      const logoY = footerY + (layout.footer.height - logoHeight) / 2;

      if (NewLogo) {
        doc.addImage(NewLogo, "PNG", logoX, logoY, logoWidth, logoHeight);
      }

      doc.setTextColor("#40484c");
      doc.setFontSize(8);
      doc.setFont("helvetica", "normal");
      doc.text(
        `Page ${pageNumber}`,
        layout.pageWidth - layout.margins.right - 10,
        footerY + 15
      );
    };

    const addSection = (title, contentArray, startY) => {
      if (!contentArray || contentArray.length === 0) return startY;

      const content = Array.isArray(contentArray)
        ? contentArray.join("\n")
        : contentArray;

      const titleHeight = 8;
      const lineHeight = 7;

      const contentLines = doc.splitTextToSize(content, contentArea.width);

      let currentY = startY;

      doc.setFontSize(12);
      doc.setFont("helvetica", "bold");
      doc.setTextColor("#000");
      doc.text(title, layout.margins.left, currentY);
      currentY += titleHeight;

      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      doc.setTextColor("#000");

      contentLines.forEach((line) => {
        if (
          currentY + lineHeight >
          layout.pageHeight - layout.footer.height - layout.margins.bottom
        ) {
          doc.addPage();
          addHeader();
          currentY = layout.header.height + layout.margins.top;
        }
        doc.text(line, layout.margins.left, currentY);
        currentY += lineHeight;
      });

      return currentY;
    };

    const addDoctorSignature = () => {
      const signatureY = layout.pageHeight - layout.footer.height - 20;

      doc.setDrawColor("#181d19");
      doc.setLineWidth(0.5);
      doc.line(
        layout.margins.left,
        signatureY,
        layout.margins.left + 60,
        signatureY
      );

      doc.setFontSize(10);
      doc.text("Doctor's Signature:", layout.margins.left, signatureY + 5);
    };

    let currentY = layout.header.height + layout.margins.top;

    addHeader();
    currentY = addSection("SUBJECTIVE", soapNote.subjective, currentY);
    currentY = addSection("OBJECTIVE", soapNote.objective, currentY);
    currentY = addSection("ASSESSMENT", soapNote.assessment, currentY);
    currentY = addSection("PLAN", soapNote.plan, currentY);

    const totalPages = doc.internal.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      addFooter(i);
    }

    addDoctorSignature();

    doc.save("SOAP_Note.pdf");
    return "SOAP Note downloaded successfully as PDF.";
  } catch (error) {
    console.error("Error while downloading the SOAP Note:", error);
    throw new Error("Failed to download SOAP Note as PDF: " + error.message);
  }
};
