import { ScreenType } from "enums";
import { DATA_CONSTANTS } from "Reducers/dataReducer/dataActionConstants";
import { logMessage } from "utils/errorLogger";

let socket = null;
let previousText;
let transcriptText = "";
let logHead = "TWILIO WEBSOCKET";

export const connectWebSocket = (
  wssUrl,
  phoneNumber,
  dispatch,
  actions,
  prevText
) => {
  previousText = prevText ? prevText : "";
  if (socket && socket.readyState === WebSocket.OPEN) {
    logMessage(
      "",
      `[ ${logHead} ] :: Closing Existing Websocket Connection `,
      false
    );
    socket.close();
  }

  let formattedNumber = "91" + phoneNumber.replace(/[^\d]/g, "");
  const fullUrl = `${wssUrl}${formattedNumber}`;
  logMessage("", `[ ${logHead} ] :: Phone Numer = ${formattedNumber} `, false);

  socket = new WebSocket(fullUrl);
  socket.onopen = () => {
    logMessage("", `[ ${logHead} ] :: Websocket Connection Opened `, false);
  };

  socket.onmessage = (e) => {
    try {
      const messageData = JSON.parse(e.data);
      logMessage(
        "",
        `[ ${logHead} ] :: Message : ${JSON.stringify(messageData)} `,
        false
      );
      if (messageData && messageData.transcription) {
        transcriptText = messageData.transcription;
        logMessage(
          "",
          `[ ${logHead} ] :: Transcription Text : ${transcriptText} `,
          false
        );
        previousText += " " + transcriptText;
        dispatch(actions.setTranscript(previousText));
      } else {
        if (messageData && messageData.message === "CALL_ENDED") {
          closeWebSocket(actions, dispatch);
        }
        logMessage(
          "",
          `[ ${logHead} ] :: Unexpected Websocket Message : ${JSON.stringify(
            messageData
          )} `,
          false
        );
      }
    } catch (error) {
      logMessage(
        "error",
        `[ ${logHead} ] :: Error Parsing Websocket Message : ${error} `,
        false
      );
      closeWebSocket(actions, dispatch);
    }
  };

  socket.onclose = () => {
    logMessage("", `[ ${logHead} ] :: Websocket connection Closed `, false);
    logMessage("", `[ ${logHead} ] :: Previous Text : ${previousText} `, false);
    dispatch(actions.setTranscript(previousText));
    dispatch(actions.setIsCallActive(false));
    socket = null;
  };

  socket.onerror = (error) => {
    logMessage(
      "error",
      `[ ${logHead} ] :: Websocket ERROR Occured : ${error} `,
      false
    );
    closeWebSocket(actions, dispatch);
  };
};

export const closeWebSocket = (actions, dispatch) => {
  if (socket) {
    logMessage("", `[ ${logHead} ] :: Closing Websocket Connection `, false);
    dispatch(actions.setIsCallRinging(false));
    dispatch({ type: DATA_CONSTANTS.SET_SCREEN, payload: ScreenType.DEFAULT });
    dispatch(actions.setIsCallActive(false));
    dispatch(actions.setIsCallAlreadyConnected(true));
    dispatch(actions.setIsCallMuted(true));
    dispatch(actions.setIsCallDisconnected(true));
    socket.close();
    socket = null;
  }
};

export const isWebSocketOpen = () =>
  socket && socket.readyState === WebSocket.OPEN;
