import React, { useRef, useEffect } from "react";
import { useSelector } from "react-redux";
import "./TabNavigation.scss";
import { LinkType, SelectedTab } from "enums";
import { logMessage } from "utils/errorLogger";

const TabNavigation = ({ selectedTab, setSelectedTab }) => {
  const { linkType } = useSelector((state) => state.data);
  const tabContainerRef = useRef(null);
  const animatedBorderRef = useRef(null);

  const getTabs = () => {
    try {
      switch (linkType) {
        case LinkType.CLINIC:
          return [
            SelectedTab.CLINIC,
            SelectedTab.QUESTIONNAIRE,
            SelectedTab.DICTATION,
            SelectedTab.AI_SUMMARY,
          ];
        case LinkType.PHONE_CALL:
          return [
            SelectedTab.PHONE_APPOINTMENT,
            SelectedTab.QUESTIONNAIRE,
            SelectedTab.DICTATION,
            SelectedTab.AI_SUMMARY,
          ];
        case LinkType.VIDEO_CALL:
          return [
            SelectedTab.VIRTUAL_APPOINTMENT,
            SelectedTab.QUESTIONNAIRE,
            SelectedTab.DICTATION,
            SelectedTab.AI_SUMMARY,
          ];
        default:
          logMessage("error", `Link type not available ,"${linkType}"`, false);
      }
    } catch (error) {
      logMessage("error", `Error fetching tabs : ${error}`, false);
      return [];
    }
  };

  const handleTabClick = (tab, index) => {
    if (!tab) {
      logMessage("error", `Invalid Tab clicked`, false);
      return;
    }
    setSelectedTab(tab);
    moveAnimatedBorder(index);
  };

  const moveAnimatedBorder = (index) => {
    try {
      if (!tabContainerRef.current || !animatedBorderRef.current) {
        logMessage(
          "error",
          "Animated Border or Tab Container not found",
          false
        );
        return;
      }

      const tabs = tabContainerRef.current.children;
      const selectedTab = tabs[index];
      if (!selectedTab) {
        logMessage("error", `Tab not found at index ${index}`, false);
        return;
      }

      const { offsetWidth, offsetLeft } = selectedTab;
      animatedBorderRef.current.style.width = `${offsetWidth}px`;
      animatedBorderRef.current.style.transform = `translateX(${offsetLeft}px)`;
    } catch (error) {
      logMessage("error", `Error moving animated border: ${error}`, false);
    }
  };

  useEffect(() => {
    try {
      const tabs = getTabs();
      const defaultIndex = tabs.indexOf(selectedTab);
      if (defaultIndex !== -1) {
        moveAnimatedBorder(defaultIndex);
      } else {
        logMessage(
          "warning",
          `Selected tab "${selectedTab}" not found in tabs`,
          false
        );
        if (tabs.length > 0) setSelectedTab(tabs[0]);
      }
    } catch (error) {
      logMessage("error", `Error getting tabs: ${error}`, false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedTab]);

  const tabs = getTabs();

  return (
    <div className="qpeTabContainer" ref={tabContainerRef}>
      {tabs.length > 0 ? (
        tabs.map((tab, index) => (
          <div
            key={tab}
            className={`qpeTabOption ${
              selectedTab === tab ? "qpeSelectedTab" : ""
            }`}
            onClick={() => handleTabClick(tab, index)}
          >
            {tab}
          </div>
        ))
      ) : (
        <div className="qpeErrorContainer">
          <p>No tabs available. Please check your configuration.</p>
        </div>
      )}
      <div className="animatedBorder" ref={animatedBorderRef}></div>
    </div>
  );
};

export default TabNavigation;
