import React, { useState } from "react";
import { useDispatch } from "react-redux";
import { setUser } from "Reducers/userReducer/userActions";
import { loginUser } from "services/authService/authService";
import "./Auth.scss";
import { TogglePassword } from "assets/Index";
import { logMessage } from "utils/errorLogger";

function Auth({ authenticated }) {
  const dispatch = useDispatch();
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isPasswordVisible, setIsPasswordVisible] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    logMessage("", "Form Submitted", false);
    try {
      const response = await loginUser({ username, password });
      dispatch(setUser(response.data.data));
      sessionStorage.setItem("JSessionID", response.data.data);
      authenticated();
    } catch (error) {
      const errorMessage =
        error.response?.data?.message || "Login failed. Please try again.";
      setError(errorMessage);

      logMessage("error", "Login attempt failed", false);
    } finally {
      setIsLoading(false);
    }
  };

  const togglePasswordVisibility = () => {
    setIsPasswordVisible((prev) => !prev);
  };

  return (
    <div className="qpeIndexMainContainer">
      <form className="authForm" onSubmit={handleSubmit}>
        <h1 className="authTitle">Sign In</h1>
        <div className="formGroup">
          <label htmlFor="username" className="label">
            Email
          </label>
          <input
            type="text"
            id="username"
            className="input"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            placeholder="Enter your email"
            required
          />
        </div>
        <div className="formGroup">
          <label htmlFor="password" className="label">
            Password
          </label>
          <div className="passwordField">
            <input
              type={isPasswordVisible ? "text" : "password"}
              id="password"
              className="input"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Password"
              required
              autoComplete="true"
            />
            <button
              type="button"
              className="togglePassword"
              onClick={togglePasswordVisibility}
            >
              <TogglePassword isVissible={isPasswordVisible} />
            </button>
          </div>
        </div>
        {error && <p className="error">{error}</p>}
        <a href="/reset-password" className="forgotPassword">
          Forget password?
        </a>
        <button
          className="submitButton"
          id="loginBtn"
          type="submit"
          disabled={isLoading}
        >
          {isLoading ? "Signing in..." : "Sign In"}
        </button>
        <p className="signUpPrompt">Don’t have an account? Sign Up</p>
      </form>
    </div>
  );
}

export default Auth;
