import "./TabContent.scss";
import React from "react";
import Transcript from "components/Transcript/Transcript";
import Summary from "components/SoapNote/SoapNote";
import AppointmentScreen from "components/AppointmentScreen/AppointmentScreen";
import Loader from "components/Loader/Loader";
import Questionnaire from "components/Questionnaire/Questionnaire";
import { SelectedTab } from "enums";
const TabContent = ({
  selectedTab,
  timer,
  patientName,
  loading,
  hasSoapNoteData,
  dispatch,
  phoneNumber,
  setTimer,
}) => {
  const renderTabContent = () => {
    if (selectedTab === SelectedTab.AI_SUMMARY && loading)
      return <Loader parent={"summary"} />;

    switch (selectedTab) {
      case SelectedTab.QUESTIONNAIRE:
        return <Questionnaire />;
      case SelectedTab.DICTATION:
        return <Transcript />;
      case SelectedTab.AI_SUMMARY:
        return <Summary hasSoapNoteData={hasSoapNoteData} />;
      default:
        return null;
    }
  };

  const appointmentScreenClass =
    selectedTab !== SelectedTab.VIRTUAL_APPOINTMENT &&
    selectedTab !== SelectedTab.CLINIC &&
    selectedTab !== SelectedTab.PHONE_APPOINTMENT
      ? "hidden"
      : "";

  return (
    <div className="qpeInnerContainer">
      <div className={appointmentScreenClass && appointmentScreenClass}>
        <AppointmentScreen
          timer={timer}
          selectedTab={selectedTab}
          patientName={patientName}
          dispatch={dispatch}
          phoneNumber={phoneNumber}
          setTimer={setTimer}
        />
      </div>
      {renderTabContent()}
    </div>
  );
};

export default TabContent;
