import axios from "axios";
import {
  setIsAppointmentQuestionnaireLoaded,
  setIsNewPatientQuestionnaireLoaded,
} from "Reducers/questionnaireReducer/questionnaireActions";
import { logMessage } from "utils/errorLogger";

const BASE_URL = process.env.REACT_APP_QUIPO_BASE_URL || "";

export const fetchQuestionnaireApi = async (id, type, dispatch) => {
  if (!BASE_URL) {
    logMessage(
      "error",
      "API base URL is not defined in the environment variables."
    );
    throw new Error(
      "API base URL is not defined in the environment variables."
    );
  }

  const url = `${BASE_URL}/fetch-questionnaire`;
  const requestBody = getRequestPayload(id, type);

  if (!requestBody) {
    logMessage(
      "error",
      `Invalid type "${type}". Expected "demographicNo" or "oscarAppointmentId".`
    );
    throw new Error(
      `Invalid type "${type}". Expected "demographicNo" or "oscarAppointmentId".`
    );
  }

  try {
    const response = await axios.post(url, requestBody, {
      headers: { "Content-Type": "application/json" },
    });

    if (response.data?.statusCode === 404) {
      const errorMessage =
        type === "oscarAppointmentId"
          ? "Not Found: Appointment Questionnaire"
          : "Not Found: New Patient Questionnaire";
      logMessage("error", errorMessage);
      dispatch(
        type === "oscarAppointmentId"
          ? setIsAppointmentQuestionnaireLoaded(true)
          : setIsNewPatientQuestionnaireLoaded(true)
      );
      return null;
    }

    return response.data.data;
  } catch (error) {
    logMessage("error", `API call failed: ${error.message}`);
    throw error;
  }
};

const getRequestPayload = (id, type) => {
  const payloadMap = {
    demographicNo: { demographicNo: id },
    oscarAppointmentId: { oscarAppointmentId: id },
  };
  return payloadMap[type] || null;
};

export const fetchPatientInfo = async (demographicId, oscarAppointmentId) => {
  try {
    const requestBody = {
      demographicNo: demographicId,
      oscarAppointmentId: oscarAppointmentId,
    };

    if (!requestBody) {
      logMessage("error", "Invalid request payload for patient info");
      throw new Error("Invalid request payload for patient info");
    }

    const response = await axios.post(`${BASE_URL}/patient-info`, requestBody, {
      headers: { "Content-Type": "application/json" },
    });

    if (response.data?.statusCode !== 200) {
      logMessage(
        "error",
        `API call failed with status code ${response.data.statusCode}`
      );
      throw new Error(
        `API call failed with status code ${response.data.statusCode}`
      );
    }

    if (response.data?.data) {
      logMessage("info", response.data.data, false);
    } else {
      logMessage("error", "Failed to fetch patient info");
    }

    return response.data?.data || null;
  } catch (error) {
    logMessage("error", error);

    throw error;
  }
};

export const uploadSOAPNote = async (
  demographicId,
  oscarAppointmentId,
  soapNote
) => {
  try {
    const response = await axios.post(`${BASE_URL}/upload-soap-note`, {
      oscarAppointmentId,
      demographicNo: demographicId,
      soapNote,
    });

    if (response.data.statusCode && response.data.statusCode !== 200) {
      logMessage("error", response.data.message || "Error uploading SOAP Note");
      throw new Error(response.data.message || "Error uploading SOAP Note");
    }

    logMessage("success", "SOAP Note generated.", false);
    return response;
  } catch (error) {
    logMessage("error", error.message || "Error uploading SOAP Note");
    throw error;
  }
};

export const fetchPreviousData = async (appointmentId) => {
  const url = `${process.env.REACT_APP_SERVER_URL}/details/${appointmentId}`;
  try {
    const response = await axios.get(url, {
      headers: { "Content-Type": "application/json" },
    });
    return response?.data;
  } catch (error) {
    if (error?.response?.data?.detail) {
      logMessage("warning", `${error.response.data.detail}`, false);
      return null;
    }
    logMessage(
      "error",
      `Fetching Previous Data failed: ${error.message}`,
      false
    );
    throw error;
  }
};
