import { showToast } from "./toastUtil";

export const logMessage = (type, message, showToastNotification = true) => {
  // Check if logging should occur based on the environment mode
  if (process.env.REACT_APP_MODE !== "development") {
    return;
  }

  switch (type) {
    case "error":
      console.error(`${message}`);
      break;
    case "warning":
      console.warn(`${message}`);
      break;
    case "info":
      console.info(`${message}`);
      break;
    default: {
      console.log(`${message}`);
      break;
    }
  }

  if (showToastNotification) {
    showToast(type, `${message}`);
  }
};
