import { ScreenType, TimerTypes } from "enums";
import React from "react";
import { useSelector } from "react-redux";

const TimerDisplay = ({ timer, type, patient, doctor }) => {
  const { doctorName, patientName, screen } = useSelector(
    (state) => state.data
  );
  const { isRecording } = useSelector((state) => state.scribe);
  const { isCallActive } = useSelector((state) => state.twilio);
  const { isVideoCallActive } = useSelector((state) => state.video);

  const formatTimer = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes.toString().padStart(2, "0")}:${secs
      .toString()
      .padStart(2, "0")}`;
  };

  const displayedPatientName = patientName || "N/A";
  const displayedDoctorName = doctorName || "N/A";

  switch (type) {
    case TimerTypes.NAME:
      if (doctor) {
        return <span>{displayedDoctorName} (You)</span>;
      }
      if (patient) {
        return <span>{displayedPatientName}</span>;
      }
      return (
        <div className="qpeTimerContainer">
          {displayedPatientName && <span>{displayedPatientName}</span>}
          {!patient && !doctor && <span>-</span>}
          {displayedDoctorName && !doctor && (
            <span>{displayedDoctorName} (You)</span>
          )}
          {!patient &&
            !doctor &&
            (isCallActive ||
              isRecording ||
              screen === ScreenType.NONE ||
              isVideoCallActive) && (
              <>
                <span>-</span>
                <span className="status">Recording</span>
              </>
            )}
        </div>
      );
    case TimerTypes.TIMER:
      return (
        <p style={{ color: "var(--white)", fontWeight: 500 }}>
          {timer !== undefined ? formatTimer(timer) : "N/A"}
        </p>
      );
    default:
      return <p style={{ color: "var(--white)", fontWeight: 500 }}>N/A</p>;
  }
};

export default TimerDisplay;
