import axios from "axios";
import { logMessage } from "utils/errorLogger";

const API_URL = process.env.REACT_APP_QUIPO_BASE_URL;

export const loginUser = async (credentials) => {
  try {
    if (!API_URL) {
      throw new Error("API URL is not defined. Please check your .env file.");
    }

    const response = await axios.post(`${API_URL}/sign-in`, credentials, {
      headers: {
        "Content-Type": "application/json",
      },
    });

    if (
      response.data?.statusCode >= 400 ||
      response.data?.message?.toLowerCase().includes("unable to get")
    ) {
      throw new Error(
        response.data.message || "Server responded with an error"
      );
    }

    return response;
  } catch (error) {
    if (error.response) {
      logMessage(
        "error",
        {
          status: error.response.status,
          data: error.response.data,
        },
        false
      );
      throw new Error(
        error.response?.data?.message || "Something went wrong on the server"
      );
    } else if (error.request) {
      logMessage("error", error.request, false);
      throw new Error("No response received from server");
    } else {
      logMessage(
        "error",
        {
          message: error.message,
        },
        false
      );
      throw new Error(error.message);
    }
  }
};
