import { useSelector } from "react-redux";
import { getInitials } from "utils/Utils";
import "./PatientProfile.scss";
import { MicIcon, MuteMicIcon } from "assets/Index";
import TimerDisplay from "components/TimerDisplay/TimerDisplay";
import { LinkType, ScreenType, TimerTypes } from "enums";

const PatientProfile = ({ size, main = true }) => {
  const { isCallMuted } = useSelector((state) => state.twilio);
  const { isPaused } = useSelector((state) => state.scribe);
  const { patientName, doctorName, screen, linkType } = useSelector(
    (state) => state.data
  );

  const getBorderStyle = () => {
    if (main && screen === ScreenType.NONE) {
      if (linkType !== LinkType.CLINIC && linkType !== LinkType.VIDEO_CALL) {
        return { border: "1px solid var(--outline)" };
      }
    }
    return {};
  };

  return (
    <div className="qpeProfileContainerMain">
      {/* Render profile container if not in VIDEO_CALL mode */}
      {!(
        linkType === LinkType.VIDEO_CALL &&
        screen === ScreenType.NONE &&
        main
      ) && (
        <div
          className={`qpeProfileContainer ${size || ""} ${
            main ? "hasBorder" : ""
          }`}
          style={getBorderStyle()}
        >
          {/* Timer Display for doctor */}
          {screen === ScreenType.NONE &&
            main &&
            linkType !== LinkType.CLINIC && (
              <TimerDisplay type={TimerTypes.NAME} patient={true} />
            )}

          {/* Patient initials */}
          <div className="qpeProfile">
            <p>{getInitials(patientName) || "N/A"}</p>
          </div>

          {/* Microphone icon */}
          {screen === ScreenType.NONE &&
            main &&
            (isCallMuted || isPaused ? (
              <MuteMicIcon color="var(--primary)" />
            ) : (
              <MicIcon color="var(--primary)" />
            ))}
        </div>
      )}

      {/* Duplicate profile container for specific case */}
      {screen === ScreenType.NONE &&
        main &&
        linkType === LinkType.VIDEO_CALL && (
          <div className="qpeProfileContainer">
            <div className="qpeProfile">
              <p>{getInitials(patientName) || "N/A"}</p>
            </div>
          </div>
        )}

      {/* Render profile container for PHONE_CALL */}
      {main &&
        linkType === LinkType.PHONE_CALL &&
        screen === ScreenType.NONE && (
          <div
            className={`qpeProfileContainer ${size || ""} ${
              main ? "hasBorder" : ""
            }`}
            style={{
              border:
                linkType === LinkType.CLINIC
                  ? undefined
                  : "1px solid var(--outline)",
            }}
          >
            {/* Timer Display for patient */}
            {screen === ScreenType.NONE && main && (
              <TimerDisplay type={TimerTypes.NAME} doctor={true}/>
            )}

            {/* Doctor initials */}
            <div className="qpeProfile">
              <p>{getInitials(doctorName) || "N/A"}</p>
            </div>

            {/* Microphone icon */}
            {screen === ScreenType.NONE &&
              (isCallMuted || isPaused ? (
                <MuteMicIcon color="var(--primary)" />
              ) : (
                <MicIcon color="var(--primary)" />
              ))}
          </div>
        )}
    </div>
  );
};

export default PatientProfile;
