import React, { useState, useEffect } from "react";
import "./Modal.scss";
import { useSelector } from "react-redux";
import { MicIcon, MusicIcon, VideoIcon } from "assets/Index";
import { LinkType } from "enums";

const Modal = ({ onClose, settings = false }) => {
  const { phoneNumber, phn, patientName, email, dob } = useSelector(
    (state) => state.data
  );
  const { linkType } = useSelector((state) => state.data);

  const [inputDevices, setInputDevices] = useState([]);
  const [outputDevices, setOutputDevices] = useState([]);
  const [videoDevices, setVideoDevices] = useState([]);
  const [selectedInput, setSelectedInput] = useState("default");
  const [selectedOutput, setSelectedOutput] = useState("default");
  const [selectedVideo, setSelectedVideo] = useState("default");

  useEffect(() => {
    const getDevices = async () => {
      try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        const inputs = devices.filter((device) => device.kind === "audioinput");
        const outputs = devices.filter(
          (device) => device.kind === "audiooutput"
        );
        const videos = devices.filter((device) => device.kind === "videoinput");

        setInputDevices(inputs);
        setOutputDevices(outputs);
        setVideoDevices(videos);

        console.log("Available Input Devices: ", inputs);
        console.log("Available Output Devices: ", outputs);
        console.log("Available Video Devices: ", videos);

        const defaultInput = inputs.find(
          (device) => device.deviceId === "default"
        );
        const defaultOutput = outputs.find(
          (device) => device.deviceId === "default"
        );
        const defaultVideo = videos.find(
          (device) => device.deviceId === "default"
        );

        if (defaultInput) setSelectedInput(defaultInput.deviceId);
        if (defaultOutput) setSelectedOutput(defaultOutput.deviceId);
        if (defaultVideo) setSelectedVideo(defaultVideo.deviceId);
      } catch (err) {
        console.error("Error fetching devices: ", err);
      }
    };

    getDevices();
  }, []);

  const patientInfo = [
    { label: "Date of Birth", value: dob, key: "dob" },
    { label: "Health Card Number", value: phn, key: "phn" },
    { label: "Phone Number", value: phoneNumber, key: "phoneNumber" },
    { label: "Email", value: email, key: "email" },
    { label: "Address", value: "Not Available", key: "address" },
  ];

  const handleDoneClick = async () => {
    if (selectedInput && selectedOutput && selectedVideo) {
      try {
        const existingStream = window.stream;
        if (existingStream) {
          const tracks = existingStream.getTracks();
          tracks.forEach((track) => track.stop());
        }

        const stream = await navigator.mediaDevices.getUserMedia({
          audio: { deviceId: selectedInput },
          ...(linkType === LinkType.VIDEO_CALL && {
            video: { deviceId: selectedVideo },
          }),
        });

        window.stream = stream;
        console.log("Media stream setup successfully");

        const usedInput = inputDevices.find(
          (device) => device.deviceId === selectedInput
        );
        const usedOutput = outputDevices.find(
          (device) => device.deviceId === selectedOutput
        );
        const usedVideo = videoDevices.find(
          (device) => device.deviceId === selectedVideo
        );

        console.log("Currently using Input Device: ", usedInput);
        console.log("Currently using Output Device: ", usedOutput);
        console.log("Currently using Video Device: ", usedVideo);

        const videoElement = document.getElementById("videoElement");
        if (videoElement && stream) {
          videoElement.srcObject = stream;
        }
        onClose();
      } catch (error) {
        console.error("Error setting up media stream:", error);
      }
    } else {
      console.error("Please select all devices before proceeding.");
    }
  };

  const deviceSettings = [
    {
      icon: <MicIcon color="var(--dark-text)" />,
      label: "Microphone",
      options: inputDevices,
      selected: selectedInput,
      onChange: (e) => setSelectedInput(e.target.value),
    },
    {
      icon: <MusicIcon isDisabled={true} color="var(--dark-text)" />,
      label: "Speaker",
      options: outputDevices,
      selected: selectedOutput,
      onChange: (e) => setSelectedOutput(e.target.value),
    },
    ...(linkType === LinkType.VIDEO_CALL
      ? [
          {
            icon: <VideoIcon color="var(--dark-text)" />,
            label: "Video",
            options: videoDevices,
            selected: selectedVideo,
            onChange: (e) => setSelectedVideo(e.target.value),
          },
        ]
      : []),
  ];

  return (
    <div className="qpe-modal-overlay">
      <div className="qpe-modal-container">
        <div className="qpe-modal-header">
          {settings ? (
            <div className="qpe-modal-sub-header">
              <h2>Settings</h2>
              <p>
                Set your microphone and speaker, test them, adjust their volume,
                view your video feed and change your camera and change other
                settings.
              </p>
            </div>
          ) : (
            <h2>{patientName || "No Name Available"}</h2>
          )}
        </div>

        <div className="qpe-modal-body">
          {settings ? (
            <div className="device-settings">
              {deviceSettings.map((setting, index) => (
                <div key={index} className="device-setting">
                  {setting.icon}
                  <label>{setting.label}</label>
                  <div className="custom-select-container">
                    <select
                      value={setting.selected}
                      onChange={setting.onChange}
                    >
                      {setting.options.map((device, index) => (
                        <option key={index} value={device.deviceId}>
                          {device.label || device.deviceId}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            patientInfo.map((item, index) => (
              <div key={item.key} className="qpe-modal-row">
                <div className="qpe-modal-info">
                  <p>{item.label}</p>
                  <p>{item.value || "Not Available"}</p>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="qpe-modal-footer">
          <button onClick={onClose}>{settings ? "Cancel" : "Close"}</button>
          {settings && <button onClick={handleDoneClick}>Done</button>}
        </div>
      </div>
    </div>
  );
};

export default Modal;
