import {
  SET_ACCORDION_DATA,
  SET_SOAP_API_DATA,
  SET_FIRST_API_QUESTIONS,
  SET_IS_APPOINTMENT_QUESTIONNAIRE_LOADED,
  SET_IS_NEW_PATIENT_QUESTIONNAIRE_LOADED,
  SET_SECOND_API_QUESTIONS,
} from "./questionnaireActionConstants";

export const setFirstApiQuestions = (questions) => ({
  type: SET_FIRST_API_QUESTIONS,
  payload: questions,
});

export const setSecondApiQuestions = (questions) => ({
  type: SET_SECOND_API_QUESTIONS,
  payload: questions,
});

export const setIsAppointmentQuestionnaireLoaded = (loaded) => ({
  type: SET_IS_APPOINTMENT_QUESTIONNAIRE_LOADED,
  payload: loaded,
});

export const setIsNewPatientQuestionnaireLoaded = (loaded) => ({
  type: SET_IS_NEW_PATIENT_QUESTIONNAIRE_LOADED,
  payload: loaded,
});

export const setAccordionData = (data) => ({
  type: SET_ACCORDION_DATA,
  payload: data,
});

export const setSoapApiData = (data) => ({
  type: SET_SOAP_API_DATA,
  payload: data,
});