import React from "react";
import "./Loader.scss";

function Loader({ parent }) {
  return (
    <div
      className="qpeLoader-container"
      style={{
        borderRadius: parent === "summary" ? "12px" : "0",
      }}
    >
      <div className="qpeSpinner"></div>
    </div>
  );
}

export default Loader;
