import { ScreenType } from "enums";
import { DATA_CONSTANTS } from "./dataActionConstants";

const initialState = {
  linkType: "",
  demoGraphicId: "",
  patientName: "",
  currentWindow: "",
  phoneNumber: "",
  appointmentNumber: "",
  dob: "",
  email: "",
  phn: "",
  inProgress: false,
  screen: ScreenType.DEFAULT,
  doctorName: "",
  previousData: {},
};

const dataReducer = (state = initialState, action) => {
  switch (action.type) {
    case DATA_CONSTANTS.SET_LINK_TYPE:
      return { ...state, linkType: action.payload };
    case DATA_CONSTANTS.SET_DEMOGRAPHIC_ID:
      return { ...state, demoGraphicId: action.payload };
    case DATA_CONSTANTS.SET_PATIENT_NAME:
      return { ...state, patientName: action.payload };
    case DATA_CONSTANTS.SET_CURRENT_WINDOW:
      return { ...state, currentWindow: action.payload };
    case DATA_CONSTANTS.SET_PHONE_NUMBER:
      return { ...state, phoneNumber: action.payload };
    case DATA_CONSTANTS.SET_APPOINTMENT_NUMBER:
      return { ...state, appointmentNumber: action.payload };
    case DATA_CONSTANTS.SET_EMAIL:
      return { ...state, email: action.payload };
    case DATA_CONSTANTS.SET_DOB:
      return { ...state, dob: action.payload };
    case DATA_CONSTANTS.SET_PHN:
      return { ...state, phn: action.payload };
    case DATA_CONSTANTS.SET_IN_PROGRESS:
      return { ...state, inProgress: action.payload };
    case DATA_CONSTANTS.CLEAR_STATES:
      return initialState;
    case DATA_CONSTANTS.SET_SCREEN:
      return { ...state, screen: action.payload };
    case DATA_CONSTANTS.SET_DOCTOR:
      return { ...state, doctorName: action.payload };
    case DATA_CONSTANTS.SET_PREVIOUS_DATA:
      return { ...state, previousData: action.payload };
    default:
      return state;
  }
};

export default dataReducer;
