import { logMessage } from "utils/errorLogger";

export const FullAudioTranscriber = (Base) =>
  class extends Base {
    processRecording() {
      this.audioBlob = new Blob(this.audioChunks, {
        type: this.config?.mimeType,
      });
      this.audioFile = new File([this.audioBlob], "recording.webm", {
        type: this.config?.mimeType,
      });
      this.audioChunks = [];
      return this.audioFile;
    }

    async transcribeFullAudio() {
      try {
        this.audioFile = this.processRecording();
        if (!this.audioFile) {
          throw new Error("No audio file to transcribe");
        }
        const formData = new FormData();
        formData.append("file", this.audioFile);

        const maxRetries = 3;
        const retryDelay = 1000; // 1 second
        let attempt = 0;
        let resultText = null;

        while (attempt < maxRetries) {
          attempt++;
          try {
            const response = await fetch(
              `${this.baseURL}/transcribe?appt_id=${this.appointmentNumber}`,
              {
                method: "POST",
                body: formData,
              }
            );

            if (!response.ok) {
              throw new Error(`HTTP error! Status: ${response.status}`);
            }

            const result = await response.json();

            if (result.length > 0 && result?.text) {
              resultText = result?.text;
              break;
            } else {
              resultText = result?.text || null;
              break;
            }
          } catch (error) {
            logMessage(
              "error",
              `Attempt ${attempt} failed: ${error.message}`,
              false
            );
            if (attempt < maxRetries) {
              await new Promise((resolve) => setTimeout(resolve, retryDelay));
            }
          }
        }

        return resultText;
      } catch (error) {
        this.logData("Transcription failed.");
        throw error;
      }
    }
  };
