import React, { useEffect, useRef, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import TimerDisplay from "components/TimerDisplay/TimerDisplay";
import PatientProfile from "components/PatientProfile/PatientProfile";
import Controllers from "components/Controllers/Controllers";
import { LinkType, ScreenType, TimerTypes } from "enums";
import { connectWebSocket } from "services/twilio/websocketService";
import { logMessage } from "utils/errorLogger";
import { DATA_CONSTANTS } from "Reducers/dataReducer/dataActionConstants";
import { getToken } from "services/videoCallServices/videoCallServices";
import { setToken } from "Reducers/videoCallReducer/videoCallActions";

export const DefaultScreen = ({
  selectedTab,
  timer,
  phoneNumber,
  isCallMuted,
  actions,
}) => {
  const dispatch = useDispatch();
  const wssUrl = process.env.REACT_APP_WSS_URL;
  const hasConnected = useRef(false);
  let timeoutId;

  const { isCallActive } = useSelector((state) => state.twilio);
  const { transcriptText } = useSelector((state) => state.scribe);
  const { linkType, appointmentNumber } = useSelector((state) => state.data);
  const [loading, setLoading] = useState(false);

  const initializeCall = () => {
    if (!isCallActive) {
      try {
        logMessage("log", "Attempting to connect to WebSocket...", false);
        hasConnected.current = true;
        dispatch({ type: DATA_CONSTANTS.SET_IN_PROGRESS, payload: true });
        connectWebSocket(wssUrl, phoneNumber, dispatch, actions, transcriptText);
        dispatch(actions.setIsCallMuted(false));
        dispatch(actions.setIsCallRinging(true));
        dispatch(actions.setIsCallActive(true));
        dispatch(actions.setIsCallAlreadyConnected(true));
        dispatch({ type: DATA_CONSTANTS.SET_SCREEN, payload: ScreenType.NONE });
      } catch (error) {
        hasConnected.current = false;
        logMessage("error", error.message, false);
      }
    } else {
      logMessage(
        "Info",
        "Skipping websocker connection as a call is active.",
        false
      );
    }
  };
  useEffect(() => {
    if (LinkType.VIDEO_CALL === linkType) {
      setLoading(true);

      if (!appointmentNumber) {
        logMessage("error", "Appointment number is required for video call");
        setLoading(false);
        return;
      }
      const fetchToken = async () => {
        try {
          const token = await getToken(appointmentNumber);
          dispatch(setToken(token));
          console.log("Token fetched successfully", token);
          setLoading(false);
        } catch (error) {
          logMessage("error", error.message, false);
        }
      };
      fetchToken();
    }
  }, [linkType, appointmentNumber, dispatch]);

  useEffect(() => {
    if (timeoutId && !isCallActive) {
      clearTimeout(timeoutId);
      logMessage("info", "Cleared timeout due to call inactivity", false);
    }
  }, [isCallActive, timeoutId]);

  return (
    <div
      className="qpeElevatedDiv"
      id={linkType === LinkType.VIDEO_CALL ? "qpeVdoCall" : undefined}
    >
      <TimerDisplay type={TimerTypes.NAME} />
      {ScreenType.DEFAULT && <PatientProfile />}
      <Controllers
        selectedTab={selectedTab}
        phoneNumber={phoneNumber}
        isCallActive={isCallActive}
        isCallMuted={isCallMuted}
        actions={actions}
        timer={timer}
        initializeCall={initializeCall}
        loading={loading}
        disabled={loading}
      />
    </div>
  );
};
