export const moveCaretToEnd = (e) => {
  const range = document.createRange();
  const selection = window.getSelection();
  range.selectNodeContents(e.target);
  range.collapse(false);
  selection.removeAllRanges();
  selection.addRange(range);
};

export const handleKeyDown = (
  section,
  index,
  tempContent,
  setTempContent,
  listRefs,
  e
) => {
  if (e.key === "Enter") {
    e.preventDefault();
    const updated = [...tempContent[section]];
    updated.splice(index + 1, 0, "");
    setTempContent((prev) => ({ ...prev, [section]: updated }));

    setTimeout(() => listRefs.current[section][index + 1]?.focus(), 0);
  } else if (e.key === "Backspace" && tempContent[section][index] === "") {
    e.preventDefault();
    const updated = [...tempContent[section]];
    updated.splice(index, 1);
    setTempContent((prev) => ({ ...prev, [section]: updated }));
    setTimeout(
      () =>
        listRefs.current[section][index - 1]?.focus() ||
        listRefs.current[section][index]?.focus(),
      0
    );
  }
};
export const getInitials = (name) => {
  if (!name) return "";
  return name
    .split(/[ ,]+/) 
    .map((word) => word.charAt(0)) 
    .join("") 
    .toUpperCase(); 
};


export const formatSOAPNote = (soapNote) => {
  if (!soapNote || typeof soapNote !== "object") {
    return "Invalid SOAP note data.";
  }

  const formatSection = (sectionName, sectionContent) => {
    if (!Array.isArray(sectionContent) || sectionContent.length === 0) {
      return ""; // Return an empty string if section is empty
    }

    return `${sectionName}:\n${sectionContent.map((item, index) => `  ${index + 1}. ${item}`).join("\n")}\n`;
  };

  const sections = ["subjective", "objective", "assessment", "plan"];
  
  // Filter out empty sections before joining
  return sections
    .map((section) => formatSection(section.charAt(0).toUpperCase() + section.slice(1), soapNote[section]))
    .filter((formattedSection) => formattedSection !== "") // Remove empty sections
    .join("\n");
};
