import React, { useEffect, useRef, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import { SET_TRANSCRIPT } from "Reducers/scribeReducer/scribeActionConstants";
import { logMessage } from "utils/errorLogger";

const Transcript = () => {
  const dispatch = useDispatch();
  const [newText, setNewText] = useState("");
  const { isRecording, transcriptText, dictationText, isPaused } = useSelector(
    (state) => state.scribe
  );
  const textAreaRef = useRef(null);
  const { inProgress } = useSelector((state) => state.data);

  useEffect(() => {
    try {
      if (transcriptText) {
        setNewText(transcriptText);
      }
    } catch (error) {
      logMessage("error", "Error updating editable text", false);
    }
  }, [transcriptText]);

  useEffect(() => {
    if (isRecording && inProgress && transcriptText && dictationText) {
      if (!transcriptText.endsWith(dictationText)) {
        setNewText(`${transcriptText} ${dictationText}`.trim());
      } else {
        setNewText(transcriptText);
      }
    }
  }, [
    isRecording,
    transcriptText,
    dictationText,
    inProgress,
    dispatch,
    newText,
  ]);

  useEffect(() => {
    if (isRecording && transcriptText && dictationText && !inProgress) {
      setNewText(`${transcriptText} ${dictationText}`.trim());
    }
  }, [isRecording, transcriptText, dictationText, inProgress]);

  useEffect(() => {
    if (!isRecording) {
      setNewText(transcriptText || "");
    }
  }, [isRecording, transcriptText]);

  // Handle changes to newText in the textarea
  const handleTextChange = (e) => {
    setNewText(e.target.value);
  };

  // Save the newText to the store when blur event occurs
  const handleBlur = () => {
    try {
      if (!isRecording && !isPaused) {
        if (newText !== transcriptText) {
          // Check if newText is different
          dispatch({ type: SET_TRANSCRIPT, payload: newText });
          sessionStorage.setItem("qpeTranscript", newText);
        }
      }
    } catch (error) {
      logMessage("error", "Error saving edited transcript", error);
    }
  };

  useEffect(() => {
    if (isRecording && !transcriptText) {
      setNewText(dictationText);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isRecording, dictationText]);

  useEffect(() => {
    if (
      isRecording &&
      transcriptText &&
      dictationText &&
      isPaused &&
      !inProgress
    ) {
      if (transcriptText && dictationText) {
        setNewText(`${transcriptText} ${dictationText}`);
      } else {
        setNewText(transcriptText);
      }
    }
  }, [
    isRecording,
    transcriptText,
    dictationText,
    isPaused,
    inProgress,
    dispatch,
  ]);

  return (
    <div className="qpeMajorTextContainer custom-scrollbar">
      <div className="qpeTextContainer custom-scrollbar">
        {dictationText || transcriptText ? (
          <textarea
            ref={textAreaRef}
            value={newText}
            onChange={handleTextChange}
            onBlur={handleBlur}
            disabled={inProgress}
            placeholder="Edit or view transcription..."
            className="qpeTextArea custom-scrollbar"
          />
        ) : (
          <div className="qpeNoData">
            <p>No transcription available.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Transcript;
