import {
  SET_VIDEO_CALL_ACTIVE,
  CLEAR_STATES,
  TOGGLE_MIC,
  TOGGLE_CAM,
  SET_TOKEN,
} from "./videoCallActionConstants";

const initialState = {
  isVideoCallActive: false,
  micOn: true,
  cameraOn: true,
  token: "",
};

const videoCallReducer = (state = initialState, action) => {
  switch (action.type) {
    case SET_VIDEO_CALL_ACTIVE:
      return { ...state, isVideoCallActive: action.payload };

    case TOGGLE_MIC:
      return { ...state, micOn: !state.micOn };

    case TOGGLE_CAM:
      return { ...state, cameraOn: !state.cameraOn };

    case SET_TOKEN:
      return { ...state, token: action.payload };

    case CLEAR_STATES:
      return initialState;
    default:
      return state;
  }
};

export default videoCallReducer;
