import { CloseIcon, NewLogo } from "assets/Index";
import React, { useState } from "react";
import "./Header.scss";
import { useDispatch, useSelector } from "react-redux";
import { stopRecording } from "Reducers/scribeReducer/scribeActions";
import { STOP_RECORDING } from "Reducers/scribeReducer/scribeActionConstants";
import { useAuthentication } from "hooks/useAuthentication";
import Modal from "components/Modal/Modal";
import PatientProfile from "components/PatientProfile/PatientProfile";
import { Toaster } from "react-hot-toast";
import { logMessage } from "utils/errorLogger";

function Header({ controller }) {
  const dispatch = useDispatch();
  const { isRecording } = useSelector((state) => state.scribe);
  const user = useAuthentication();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { patientName } = useSelector((state) => state.data);
  const { isCallActive, isCallRinging } = useSelector((state) => state.twilio);

  const handleModal = () => {
    setIsModalOpen(!isModalOpen);
  };

  const handleClose = () => {
    controller.abort();
    if (isCallActive || isCallRinging) {
      return logMessage("info", "The call is active, can't close the window");
    }

    if (isRecording) {
      return logMessage(
        "info",
        "The Recording is active, can't close the window"
      );
    }

    const removeElement = (id) => {
      const element = document.getElementById(id);
      if (element?.parentNode) {
        element.parentNode.removeChild(element);
      }
      window.location.reload();
    };

    // Stop recording if active
    if (isRecording) {
      dispatch(stopRecording({ type: STOP_RECORDING, payload: false }));
    }

    // Remove app div and script
    removeElement("react-chrome-extension");
    removeElement("react-app-script");
  };

  return (
    <div className="qpeHeader">
      <div className="qpeSubHeader">
        <div className="qpeHeaderLeft">
          <NewLogo />
        </div>
        <Toaster
          toastOptions={{
            duration: 3000,
          }}
        />
        <div className="qpeHeaderRight">
          {patientName && (
            <div
              aria-label="Open Patient Profile"
              style={{
                display: "flex",
                alignItems: "center",
                cursor: "pointer",
              }}
              onClick={handleModal}
            >
              {user && <PatientProfile main={false} size="small" />}
            </div>
          )}
          <button className="qpeCloseButton" onClick={handleClose}>
            <CloseIcon />
          </button>
        </div>
      </div>
      {isModalOpen && <Modal onClose={handleModal} />}
    </div>
  );
}

export default Header;
