import {
  START_RECORDING,
  STOP_RECORDING,
  PAUSE_RECORDING,
  RESUME_RECORDING,
  SET_TRANSCRIPT,
  SET_ERROR,
  SET_SOAP_NOTE,
  SET_DICTATION,
  SET_STOPPING,
  CLEAR_STATES,
  SET_RESPONSE_COUNT,
  SET_IS_SOAP_NOTE_LOADED,
} from "./scribeActionConstants";

const initialState = {
  transcriptText: "",
  isRecording: false,
  isPaused: false,
  error: null,
  soapNotes: [],
  responseCount: 1,
  soapNote: null,
  dictationText: "",
  isSoapNoteLoaded: null,
};

export default function scribeReducer(state = initialState, action) {
  switch (action.type) {
    case START_RECORDING:
      return { ...state, isRecording: true, isPaused: false, error: null };

    case STOP_RECORDING:
      return {
        ...state,
        isRecording: false,
        isPaused: false,
        isStopping: false,
        transcriptText: action.payload,
        error: null,
      };

    case PAUSE_RECORDING:
      return { ...state, isPaused: true };

    case RESUME_RECORDING:
      return { ...state, isPaused: false };

    case SET_TRANSCRIPT:
      return { ...state, transcriptText: action.payload };

    case SET_SOAP_NOTE: {
      if (state.soapNotes.length === 0) {
        return {
          ...state,
          soapNotes: [action.payload],
          soapNote: action.payload,
        };
      } else {
        return {
          ...state,
          soapNotes: [...state.soapNotes.flat(), action.payload],
          soapNote: action.payload,
        };
      }
    }

    case SET_ERROR:
      return { ...state, error: action.payload };

    case SET_DICTATION:
      return { ...state, dictationText: action.payload };

    case SET_STOPPING:
      return { ...state, isStopping: action.payload };

    case CLEAR_STATES:
      return initialState;

    case SET_RESPONSE_COUNT: {
      const { payload } = action;
      const updatedSoapNote = state.soapNotes[payload - 1] || null;

      return {
        ...state,
        responseCount: payload,
        soapNote: updatedSoapNote,
      };
    }

    case SET_IS_SOAP_NOTE_LOADED:
      return { ...state, isSoapNoteLoaded: action.payload };
    default:
      return state;
  }
}
