import { useEffect, useState } from "react";
import { logMessage } from "utils/errorLogger";

export const useAuthentication = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    try {
      const user = sessionStorage.getItem("JSessionID");
      if (user) {
        setIsAuthenticated(true);
        logMessage("success", "User is authenticated.", "", false);
      } else {
        setIsAuthenticated(false);
        logMessage(
          "error",
          "No user session found. User is not authenticated.",
          false
        );
      }
    } catch (error) {
      logMessage(
        "error",
        "Error accessing session storage for authentication.",
        error
      );
      setIsAuthenticated(false);
    }
  }, []);

  return isAuthenticated;
};
