
import { loginUser } from "services/authService/authService";
import { USER_CONSTANT } from "./userActionContants";


export const loginRequest = () => {
    return {
        type: USER_CONSTANT.LOGIN_REQUEST,
    };
};

export const setUser = (user) => ({
    type: USER_CONSTANT.LOGIN_SUCCESS,
    payload: user,
});

export const loginSuccess = (userData) => {
    return {
        type: USER_CONSTANT.LOGIN_SUCCESS,
        payload: userData,
    };
};


export const loginFailure = (error) => {
    return {
        type: USER_CONSTANT.LOGIN_FAILURE,
        payload: error,
    };
};


export const login = (credentials) => {
    return async (dispatch) => {
        dispatch(loginRequest());
        try {
            const response = await loginUser(credentials);
            dispatch(loginSuccess(response.data));
            sessionStorage.setItem("JSessionID", response.data.token);
        } catch (error) {
            dispatch(loginFailure(error.response?.data?.message || "Login failed"));
        }
    };
};
