import React from "react";

const Button = ({
  onClick,
  icon,
  ariaLabel,
  className = "",
  disabled = false,
  id = "",
  text,
}) => {
  const buttonClass =
    text === "Regenerate" || text === "Download" || text === "Join"
      ? className
      : `qpeScribe-button ${className}`;

  return (
    <button
      onClick={onClick}
      className={buttonClass}
      aria-label={ariaLabel}
      disabled={disabled}
      id={id}
    >
      {icon}
      {text && <span>{text}</span>}
    </button>
  );
};

export default React.memo(Button);
