import { logMessage } from "utils/errorLogger";
import {
  SET_VIDEO_CALL_ACTIVE,
  CLEAR_STATES,
  TOGGLE_MIC,
  TOGGLE_CAM,
  SET_TOKEN,
} from "./videoCallActionConstants";

// Set the active state of the video call
export const setVideoCallActive = (isActive) => ({
  type: SET_VIDEO_CALL_ACTIVE,
  payload: isActive,
});

// Clear video call states
export const setVideoCallDataClear = () => ({
  type: CLEAR_STATES,
});

// Toggle microphone state
export const toggleMic = () => ({
  type: TOGGLE_MIC,
});

export const toggleCam = () => ({
  type: TOGGLE_CAM,
});
// Set the token for video call
export const setToken = (token) => ({
  type: SET_TOKEN,
  payload: token,
});

// Start the video call
export const startVideoCall = () => {
  return async (dispatch) => {
    try {
      logMessage("success", "Starting video call");

      dispatch(setVideoCallActive(true));

      console.log("Video call is active now.");
    } catch (error) {
      console.error("Error while initiating the video call:", error);
      logMessage("error", "Error while initiating the video call", error);
      dispatch(setVideoCallActive(false));
    }
  };
};

// End the video call
export const endVideoCall = () => {
  return async (dispatch) => {
    try {
      console.log("Ending video call.");
      logMessage("success", "Ending video call");

      dispatch(setVideoCallActive(false));
    } catch (error) {
      console.error("Error while ending the video call:", error);
      logMessage("error", "Error while ending the video call", error);
    }
  };
};
