import React, { useCallback, useMemo, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  MicIcon,
  MuteMicIcon,
  VideoIcon,
  PhoneIcon,
  StopIcon,
  StatusIcon,
  ShareScreen,
  SettingsIcon,
  ParticipantIcon,
} from "assets/Index";
import { closeWebSocket } from "services/twilio/websocketService";
import {
  startRecording,
  stopRecording,
  pauseRecording,
  resumeRecording,
  setStopping,
  setSoapNote,
  setResponseCount,
} from "Reducers/scribeReducer/scribeActions";
import Button from "components/Button/Button";
import { uploadSOAPNote } from "services/apiService/apiService";
import { formatSOAPNote } from "utils/Utils";
import { logMessage } from "utils/errorLogger";
import { DATA_CONSTANTS } from "Reducers/dataReducer/dataActionConstants";
import { fetchSoapNote } from "services/soapNoteService";
import { setScreen } from "Reducers/dataReducer/dataActions";
import { LinkType, ScreenType, SelectedTab, TimerTypes } from "enums";
import TimerDisplay from "components/TimerDisplay/TimerDisplay";
import { downloadedSOAPNote } from "services/SoapNoteDownloader/SoapNoteDownloader";
import "./Controller.scss";
import {
  endVideoCall,
  startVideoCall,
  toggleCam,
} from "Reducers/videoCallReducer/videoCallActions";
import { SmallLoader } from "components/SmallLoader/SmallLoader";
import Modal from "components/Modal/Modal";

const Controllers = ({
  selectedTab,
  isCallActive,
  isCallMuted,
  actions,
  type,
  timer,
  selectedSOAP,
  initializeCall,
  videoTrack,
  micTrack,
  videoContainerRef,
  loading,
  totalUsers,
  disabled,
}) => {
  const dispatch = useDispatch();
  const { soapApiData } = useSelector((state) => state.questionnaire);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const { soapNotes } = useSelector((state) => state.scribe);
  const [isLoadingRegenerate, setIsLoadingRegenerate] = useState(false);
  const [isLoadingSave, setIsLoadingSave] = useState(false);
  const [isModal, setIsModal] = useState(false);
  const { isRecording, isPaused, isStopping, transcriptText } = useSelector(
    (state) => state.scribe
  );
  const { appointmentNumber, screen, demoGraphicId, linkType } = useSelector(
    (state) => state.data
  );
  const { isVideoCallActive, micOn, cameraOn } = useSelector(
    (state) => state.video
  );

  const isButtonDisabled =
    isLoadingRegenerate ||
    isCallActive ||
    isRecording ||
    isVideoCallActive ||
    isLoadingSave;

  const handleRegenerateSoapNote = useCallback(
    (transcriptText) => {
      setIsLoadingRegenerate(true);
      fetchSoapNote(transcriptText, soapApiData, appointmentNumber)
        .then((result) => {
          const newSoapNote = result?.soapnote || {
            subjective: [],
            objective: [],
            assessment: [],
            plan: [],
          };
          logMessage("success", "SOAP note generated successfully");
          dispatch(setSoapNote(newSoapNote));
          dispatch(setResponseCount(soapNotes.length + 1));
          setIsLoadingRegenerate(false);
        })
        .catch((error) => {
          logMessage("error", `Error regenerating SOAP note: ${error.message}`);
          setIsLoadingRegenerate(false);
        });
    },
    [soapApiData, appointmentNumber, dispatch, soapNotes.length]
  );

  const handleSOAPNoteUpload = useCallback(
    async (selectedSOAP) => {
      setIsLoadingSave(true);
      try {
        const formattedSOAPNote = formatSOAPNote(selectedSOAP);
        await uploadSOAPNote(
          demoGraphicId,
          appointmentNumber,
          formattedSOAPNote
        );
        logMessage("success", "SOAP Note uploaded successfully.");
      } catch (error) {
        logMessage("error", `SOAP Note Upload failed: ${error.message}`);
      } finally {
        setIsLoadingSave(false);
      }
    },
    [demoGraphicId, appointmentNumber]
  );

  const handleDownloadSOAP = useCallback(async (soapNote) => {
    if (!soapNote) {
      logMessage("error", "No SOAP Note provided for download.");
      return;
    }

    setIsLoadingSave(true);

    try {
      const result = await downloadedSOAPNote(soapNote);
      logMessage("success", result);
    } catch (error) {
      logMessage("error", `SOAP Note PDF Download failed: ${error.message}`);
    } finally {
      setIsLoadingSave(false);
    }
  }, []);

  const handleRecording = useCallback(
    async (action) => {
      try {
        if (action === stopRecording) {
          dispatch(setStopping(true));
          await dispatch(action());
          dispatch(setStopping(false));
          logMessage("success", "Recording stopped successfully.", false);
        } else {
          dispatch(action(appointmentNumber));
          logMessage("success", "Recording", false);
        }
      } catch (error) {
        logMessage("error", error);
      }
    },
    [dispatch, appointmentNumber]
  );

  const handleVideoCall = useCallback(
    async (action) => {
      try {
        if (action === startVideoCall) {
          dispatch(setScreen(ScreenType.NONE));
          await dispatch(action());
          dispatch({
            type: DATA_CONSTANTS.SET_SCREEN,
            payload: ScreenType.NONE,
          });
          logMessage("info", "Video Call started");
        } else if (action === endVideoCall) {
          await dispatch(action());
          dispatch({
            type: DATA_CONSTANTS.SET_SCREEN,
            payload: ScreenType.DEFAULT,
          });
          logMessage("info", "Video Call ended");
        }
      } catch (error) {
        logMessage("error", `Error handling the video call ${error} `);
      }
    },
    [dispatch]
  );

  const toggleMute = useCallback(() => {
    try {
      const action = actions.setIsCallMuted(!isCallMuted);
      dispatch(action);
      logMessage("success", "Call Controls", false);
    } catch (error) {
      logMessage("error", "Call Controls", error);
    }
  }, [dispatch, actions, isCallMuted]);

  const toggleMicForVideo = useCallback(
    async (micTrack) => {
      if (!micTrack) {
        logMessage("error", "Video Controls", "No mic track found");
        return;
      }
      micTrack.setMuted(!micTrack._muted);

      // micTrack._muted = !micTrack._muted;
      dispatch({ type: "TOGGLE_MIC" });
    },
    [dispatch]
  );

  const handleVideoCam = useCallback(
    async (videoTrack, videoContainerRef) => {
      if (!videoTrack) {
        console.log("No video track found");
        return;
      }

      try {
        if (cameraOn) {
          // await videoTrack.stop();
          // await videoTrack.setMuted(true);
          dispatch(toggleCam());
        } else {
          // await videoTrack.setMuted(false);
          // if (videoContainerRef) {
          //   await videoTrack.play(videoContainerRef.current);
          // }
          dispatch(toggleCam());
        }
      } catch (error) {
        console.log("Error toggling camera");
      }
    },
    [dispatch, cameraOn]
  );

  const handleSettingsModal = useCallback(() => {
    setIsModal(!isModal);
  }, [isModal]);

  const Loader = ({ color = "var(--dark-text)" }) => {
    return <div className="smLoader" style={{ borderTopColor: color }}></div>;
  };

  const StatusComponent = () => {
    return (
      <div className="statusContainer">
        <StatusIcon />
        <span>Dictation On</span>
      </div>
    );
  };

  const SettingComponent = () => {
    return (
      <Button
        icon={<SettingsIcon />}
        onClick={handleSettingsModal}
        className="qpeScribe-button"
      />
    );
  };

  const handleNavigation = useCallback(() => {
    if (!appointmentNumber) {
      logMessage("error", "Appointment number is required");
      return;
    }

    switch (linkType) {
      case LinkType.CLINIC:
        handleRecording(startRecording);
        break;
      case LinkType.PHONE_CALL:
        initializeCall();
        break;
      case LinkType.VIDEO_CALL:
        handleVideoCall(startVideoCall);
        break;
      default:
        logMessage("error", "Invalid link type");
        break;
    }
  }, [
    appointmentNumber,
    linkType,
    handleRecording,
    initializeCall,
    handleVideoCall,
  ]);

  const recordingControls = useMemo(() => {
    if (isStopping) {
      return (
        <Button
          text={"Stopping"}
          icon={<Loader color="#fff" />}
          className="greenButton"
          disabled
        />
      );
    }
    return (
      <>
        {isPaused ? (
          <Button
            onClick={() => handleRecording(resumeRecording)}
            icon={<MuteMicIcon />}
            ariaLabel="Resume Recording"
            id="resumeBtn"
          />
        ) : (
          <Button
            onClick={() => handleRecording(pauseRecording)}
            icon={<MicIcon color="var(--white)" />}
            ariaLabel="Pause Recording"
            id="pauseBtn"
          />
        )}
        <SettingComponent />
        <StatusComponent />

        <Button
          onClick={() => handleRecording(stopRecording)}
          icon={<StopIcon />}
          text={<TimerDisplay timer={timer} type={TimerTypes.TIMER} />}
          ariaLabel="Stop Recording"
          className={"hangupIcon"}
        />
      </>
    );
  }, [isPaused, isStopping, handleRecording, timer]);

  const renderTabControls = useMemo(() => {
    const joinButtonText =
      linkType === LinkType.VIDEO_CALL
        ? "Start video Call"
        : linkType === LinkType.PHONE_CALL
        ? "Start Phone Call"
        : "Start Recording";

    const joinButtonIcon =
      linkType === LinkType.VIDEO_CALL ? (
        <VideoIcon />
      ) : linkType === LinkType.CLINIC ? (
        <MicIcon color="var(--white)" />
      ) : LinkType.PHONE_CALL ? (
        <PhoneIcon />
      ) : (
        <MicIcon color="var(--white)" />
      );

    const joinButtonId =
      linkType === LinkType.VIDEO_CALL
        ? "video-call-button"
        : linkType === LinkType.CLINIC
        ? "clinic-recording-button"
        : linkType === LinkType.PHONE_CALL
        ? "phone-call-button"
        : "default-button";

    const joinButton = (
      <Button
        id={!loading && joinButtonId}
        icon={loading ? <SmallLoader /> : joinButtonIcon}
        text={joinButtonText}
        className="qpeSummaryButton greenButton"
        disabled={loading || disabled}
        onClick={() => handleNavigation()}
      />
    );

    return {
      Phone: (
        <>
          {screen === ScreenType.DEFAULT && !isCallActive ? (
            joinButton
          ) : (
            <>
              <Button
                onClick={toggleMute}
                icon={
                  isCallMuted ? (
                    <MuteMicIcon />
                  ) : (
                    <MicIcon color="var(--white)" />
                  )
                }
                ariaLabel="Mute Call"
                disabled={!isCallActive}
                id="mute-button"
                className="qpeScribe-button"
              />
              <SettingComponent />
              <StatusComponent />
              <Button
                onClick={() => closeWebSocket(actions, dispatch)}
                icon={<StopIcon type="call" />}
                ariaLabel="End Call"
                disabled={!isCallActive}
                id="hangup-button"
                className={"hangupIcon"}
                text={<TimerDisplay timer={timer} type={TimerTypes.TIMER} />}
              />
            </>
          )}
        </>
      ),
      Clinic: (
        <>
          {screen === ScreenType.DEFAULT && !isRecording ? (
            joinButton
          ) : (
            <>{recordingControls}</>
          )}
        </>
      ),
      Video: (
        <>
          {screen === ScreenType.DEFAULT ? (
            !isVideoCallActive && joinButton
          ) : (
            <>
              {type === "join" ? (
                <Button
                  text={"Join"}
                  className="qpeSummaryButton"
                  onClick={() => handleVideoCall(startVideoCall)}
                />
              ) : (
                <>
                  <Button
                    icon={micOn ? <MicIcon /> : <MuteMicIcon />}
                    onClick={() => toggleMicForVideo(micTrack)}
                  />
                  <Button
                    icon={
                      cameraOn ? <VideoIcon /> : <VideoIcon isDisabled={true} />
                    }
                    onClick={() =>
                      handleVideoCam(videoTrack, videoContainerRef)
                    }
                  />
                  <Button
                    icon={<ShareScreen />}
                    ariaLabel="Share Screen"
                    id="shareScreen"
                    className="qpeScribe-button"
                  />
                  <SettingComponent />
                  <StatusComponent />
                  <div className="participantIconContainer">
                    <ParticipantIcon />
                    <p>{totalUsers}</p>
                  </div>
                  <Button
                    onClick={() => {
                      handleVideoCall(endVideoCall);
                      closeWebSocket(actions, dispatch);
                    }}
                    icon={<StopIcon type="call" />}
                    ariaLabel="End Call"
                    disabled={!isVideoCallActive}
                    className={"hangupIcon"}
                    text={<TimerDisplay timer={timer} />}
                  />
                </>
              )}
            </>
          )}
        </>
      ),
      "AI Summary": (
        <>
          <Button
            text="Regenerate"
            className="qpeSummaryButton"
            onClick={() => handleRegenerateSoapNote(transcriptText)}
            disabled={isLoadingRegenerate || isButtonDisabled}
          />
          <Button
            text="Download"
            className="qpeSummaryButton"
            onClick={() => handleDownloadSOAP(selectedSOAP)}
            disabled={isLoadingSave || !soapNotes.length}
          />
          <Button
            text="Save"
            className="qpeSummaryButton save"
            onClick={() => handleSOAPNoteUpload(selectedSOAP)}
            disabled={isLoadingSave || !soapNotes.length}
          />
        </>
      ),
    };
  }, [
    isCallActive,
    isCallMuted,
    toggleMute,
    actions,
    dispatch,
    recordingControls,
    handleSOAPNoteUpload,
    selectedSOAP,
    soapNotes.length,
    isLoadingRegenerate,
    isLoadingSave,
    handleDownloadSOAP,
    screen,
    type,
    isButtonDisabled,
    cameraOn,
    disabled,
    handleNavigation,
    handleRegenerateSoapNote,
    handleVideoCall,
    handleVideoCam,
    isRecording,
    isVideoCallActive,
    linkType,
    loading,
    micOn,
    micTrack,
    timer,
    toggleMicForVideo,
    totalUsers,
    transcriptText,
    videoContainerRef,
    videoTrack,
  ]);

  return (
    <div
      className="qpeMainButtonContainer"
      style={{
        padding: selectedTab === SelectedTab.AI_SUMMARY ? "10px 10px" : "",
      }}
    >
      {renderTabControls[selectedTab] || null}
      {isModal ? (
        <Modal onClose={() => handleSettingsModal()} settings={true} />
      ) : null}
    </div>
  );
};

export default React.memo(Controllers);
